/* Lumière Cinema · Vanilla JavaScript · No API, passwords or real payments. */
(function(){
'use strict';
const D=window.NOVA_DATA,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='lumiere-demo-v1',HOLD_KEY='lumiere-holds-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('vi-VN').format(v)+'đ';
const dateLabel=(d,opts={day:'2-digit',month:'2-digit',year:'numeric'})=>new Intl.DateTimeFormat('vi-VN',{...opts,timeZone:D.tz}).format(new Date(d+'T12:00:00+07:00'));
const img=(name,alt='',cls='')=>`<img class="${cls}" src="assets/images/${esc(name)}.svg" alt="${esc(alt)}" loading="lazy">`;
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',play:'<path d="m9 5 11 7-11 7Z"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Z"/><path d="M16 5v3m0 3v2m0 3v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',print:'<path d="M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',seat:'<path d="M5 13V6a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v7M3 10v8h18v-8M6 18v4m12-4v4M4 14h16"/>',logout:'<path d="M9 3H3v18h6m6-15 6 6-6 6m-9-6h15"/>'};
const ic=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
let storageOK=true,memory={};
function read(k,fallback){try{const raw=localStorage.getItem(k);return raw?JSON.parse(raw):fallback}catch(e){storageOK=false;return memory[k]||fallback}}
function write(k,v){memory[k]=v;try{localStorage.setItem(k,JSON.stringify(v))}catch(e){storageOK=false}}
let state=read(KEY,null);if(!state||state.version!==1)state={version:1,city:'TP. Hồ Chí Minh',user:null,profiles:{},booking:null,orders:[]};
let owner;try{owner=sessionStorage.getItem('lumiere-tab')||crypto.randomUUID();sessionStorage.setItem('lumiere-tab',owner)}catch{owner='tab-'+Math.random().toString(36).slice(2)}
const save=()=>write(KEY,state);
let route,query,returnTo='#/account',pendingAuth=null,paymentBusy=false,toastTimer;
const movie=id=>D.movies.find(x=>x.id===id),cinema=id=>D.cinemas.find(x=>x.id===id),show=id=>D.showtimes.find(x=>x.id===id);
const go=p=>{if(location.hash===p)render();else location.hash=p};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function empty(title,body,action='Xem lịch chiếu',href='#/schedule'){return `<div class="empty">${ic('ticket')}<h3>${esc(title)}</h3><p>${esc(body)}</p><a class="btn" href="${href}">${action}${ic('arrow')}</a></div>`}
function title(kicker,heading,body='',action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${heading}</h1>${body?`<p>${body}</p>`:''}</div>${action}</div>`}
const badge=m=>`<span class="age age-${m.age}">${m.age}</span>`;
function heading(kicker,text,href,label='Xem tất cả'){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2>${text}</h2></div>${href?`<a class="text-link" href="${href}">${label} ${ic('arrow')}</a>`:''}</div>`}
function seed(){if(state.seeded)return;const s=D.showtimes.find(s=>s.movieId==='tang-may'&&s.cinemaId==='riverside'&&s.date===D.days[1]);const base={show:{...s},movie:{...movie(s.movieId)},cinema:{...cinema(s.cinemaId)},room:{...D.roomOf(s)},seats:[{...D.seatsFor(s).find(seat=>seat.type==='VIP'&&seat.state==='free'),category:'Người lớn',price:D.price(s,D.seatsFor(s).find(seat=>seat.type==='VIP'&&seat.state==='free'))}],foods:[],ticketTotal:90000,foodTotal:0,discount:0,total:90000,payment:'Thẻ nội địa (mô phỏng)',contact:{name:'Minh Anh',email:'demo@lumiere.local',phone:'0901234567'},userId:'demo@lumiere.local',createdAt:Date.now(),code:'LM-DEMO01',status:'paid',used:false};state.orders.push(base,JSON.parse(JSON.stringify({...base,code:'LM-DEMO02',show:{...base.show,id:base.show.id.replace(base.show.date,dateOffset(-6)),date:dateOffset(-6)},used:true})),JSON.parse(JSON.stringify({...base,code:'LM-DEMO03',status:'failed',used:false})));for(const o of state.orders){for(const seat of o.seats)seat.price=D.price(o.show,seat,seat.category);o.ticketTotal=o.seats.reduce((a,seat)=>a+seat.price,0);o.total=o.ticketTotal+o.foodTotal-o.discount}state.seeded=true;save()}
function dateOffset(n){const dt=new Date(D.today+'T12:00:00+07:00');dt.setDate(dt.getDate()+n);return new Intl.DateTimeFormat('en-CA',{timeZone:D.tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(dt)}
seed();
function header(){const isBooking=route.startsWith('/booking/');$('#site-header').innerHTML=`<div class="demo-bar"><span>ĐIỆN ẢNH BẮT ĐẦU TỪ MỘT CUỘC HẸN</span><a href="#/support/demo">Website minh họa · Không giao dịch thật ${ic('info')}</a></div><header class="header"><a class="brand" href="#/" aria-label="Lumière Cinema, trang chủ"><span class="brand-symbol">L<span></span></span><span>lumière<small>CINEMA</small></span></a>${isBooking?`<span class="booking-header-label">Đặt vé trực tuyến <span class="muted">/ An tâm từng bước</span></span>`:`<nav class="desktop-nav" aria-label="Điều hướng chính">${[['/movies','Phim'],['/schedule','Lịch chiếu'],['/cinemas','Rạp chiếu'],['/offers','Ưu đãi'],['/membership','Thành viên']].map(([p,t])=>`<a class="${route.startsWith(p)?'active':''}" href="#${p}">${t}</a>`).join('')}</nav>`}<div class="header-actions"><label class="city-select">${ic('pin')}<span class="sr-only">Chọn tỉnh thành</span><select id="city" aria-label="Tỉnh thành">${['TP. Hồ Chí Minh','Hà Nội'].map(c=>`<option ${c===state.city?'selected':''}>${c}</option>`).join('')}</select></label><a class="icon-button search-button" href="#/search" aria-label="Tìm kiếm">${ic('search')}</a><a class="account-link" href="#/${state.user?'account':'login'}">${ic('user')}<span>${state.user?esc(state.user.name.split(' ').pop()):'Đăng nhập'}</span></a><button class="icon-button mobile-menu" data-action="menu" aria-expanded="false" aria-label="Mở điều hướng">${ic('menu')}</button></div></header><nav class="mobile-nav" aria-label="Điều hướng di động" hidden>${[['/movies','Phim'],['/schedule','Lịch chiếu'],['/cinemas','Rạp chiếu'],['/offers','Ưu đãi'],['/membership','Thành viên'],['/search','Tìm kiếm'],['/tickets','Vé của tôi'],['/lookup','Tra cứu đơn'],['/support','Hỗ trợ']].map(([p,t])=>`<a href="#${p}">${t}</a>`).join('')}</nav>`;
$('#site-footer').innerHTML=`<footer class="footer"><div class="container footer-grid"><div><a class="brand" href="#/"><span class="brand-symbol">L<span></span></span><span>lumière<small>CINEMA</small></span></a><p>Mỗi thước phim, một thế giới.<br>Mỗi cuộc hẹn, một điều đáng nhớ.</p><span class="footer-note">Thương hiệu và địa chỉ hoàn toàn hư cấu.</span></div><div><h3>Khám phá</h3><a href="#/movies">Phim đang chiếu</a><a href="#/cinemas">Hệ thống rạp</a><a href="#/membership">Lumière Club</a><a href="#/offers">Ưu đãi</a></div><div><h3>Bạn cần hỗ trợ?</h3><a href="#/tickets">Vé của tôi</a><a href="#/lookup">Tra cứu đơn đặt vé</a><a href="#/support">Câu hỏi thường gặp</a><a href="#/support/contact">Liên hệ với chúng tôi</a></div><div><h3>Thông tin</h3><a href="#/policy/terms">Điều khoản sử dụng</a><a href="#/policy/privacy">Chính sách bảo mật</a><a href="#/policy/purchase">Điều kiện mua vé</a><button class="footer-reset" data-action="reset">Khôi phục dữ liệu mẫu</button></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Lumière Cinema. Made for movie moments.</span><span>Giá và chính sách chỉ để minh họa · Giờ Việt Nam (UTC+7)</span></div></footer>`;
}
function movieCard(m){return `<article class="movie-card"><a class="poster" href="#/movie/${m.id}">${img(m.art,'Poster minh họa phim '+m.title)}<span class="poster-badge">${badge(m)}</span><span class="poster-arrow">${ic('arrow')}</span></a><div class="movie-card-info"><p class="movie-meta">${esc(m.genre)} <span>·</span> ${m.duration} phút</p><h3><a href="#/movie/${m.id}">${esc(m.title)}</a></h3><div class="movie-card-bottom">${m.status==='now'?`<span class="format-label">${m.formats.join(' / ')}</span><a class="card-book" href="#/movie/${m.id}?booking=1">Đặt vé ${ic('ticket')}</a>`:`<span class="muted">Dự kiến ${dateLabel(m.release,{day:'2-digit',month:'2-digit'})}</span><a class="text-link" href="#/movie/${m.id}">Chi tiết ${ic('arrow')}</a>`}</div></div></article>`}
function offerCard(o){return `<article class="offer-card" style="--offer-color:${o.color}"><a class="offer-art ${o.kind}" href="#/offer/${o.id}"><span class="offer-art-label">LUMIÈRE ${o.kind==='member'?'CLUB':'MOMENTS'}</span><span class="offer-art-text">${o.kind==='welcome'?'HELLO,<br>MOVIE!':o.kind==='food'?'BẮP NGON.<br>PHIM HAY.':'YOUR<br>NEXT LEVEL.'}</span><span class="offer-art-icon">${ic(o.kind==='food'?'ticket':o.kind==='member'?'star':'play')}</span></a><div><span class="eyebrow">${o.kind==='member'?'Thành viên':'Ưu đãi minh họa'}</span><h3><a href="#/offer/${o.id}">${o.title}</a></h3><p>${o.subtitle}</p><a class="text-link" href="#/offer/${o.id}">Khám phá ngay ${ic('arrow')}</a></div></article>`}
function cinemaCard(c){return `<article class="cinema-card"> <a href="#/cinema/${c.id}">${img(c.id,'Không gian minh họa '+c.name)}</a><div><span class="eyebrow">${esc(c.city)} · ${esc(c.district)}</span><h3><a href="#/cinema/${c.id}">${esc(c.name)}</a></h3><p>${ic('pin')}${esc(c.address)}</p><div class="tags">${[...new Set(c.rooms.map(r=>r.type))].map(t=>`<span>${t}</span>`).join('')}</div><a class="text-link" href="#/cinema/${c.id}">Xem lịch chiếu ${ic('arrow')}</a></div></article>`}
function quickBook(){return `<form id="quick-book" class="quick-book"><div class="quick-label">${ic('ticket')}<strong>Đặt vé nhanh</strong><span>Chọn một cuộc hẹn</span></div><label><span>01 / Phim</span><select name="movie" required><option value="">Bạn muốn xem gì?</option>${D.movies.filter(m=>m.status==='now').map(m=>`<option value="${m.id}">${m.title}</option>`).join('')}</select></label><label><span>02 / Rạp chiếu</span><select name="cinema" required><option value="">Chọn rạp của bạn</option>${D.cinemas.filter(c=>c.city===state.city).map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label><span>03 / Ngày xem</span><select name="date">${D.days.map((d,i)=>`<option value="${d}">${i===0?'Hôm nay':i===1?'Ngày mai':dateLabel(d,{weekday:'short'})}, ${dateLabel(d,{day:'2-digit',month:'2-digit'})}</option>`).join('')}</select></label><button class="btn" type="submit">Tìm suất ${ic('arrow')}</button></form>`}
function home(){const m=D.movies[0];return `<section class="hero"><img class="hero-art" src="assets/images/hero.svg" alt="Thành phố tương lai giữa những tầng mây, minh họa phim Dưới tầng mây"><div class="container hero-content"><div class="hero-copy"><span class="eyebrow light">ĐANG CHIẾU · LUMIÈRE ĐỀ CỬ</span><div class="hero-rating">${badge(m)}<span>128 phút</span><span>2D / 3D</span></div><h1>DƯỚI<br>TẦNG <em>MÂY</em></h1><p>Khi bầu trời không còn là giới hạn.<br>Một hành trình để tìm thấy nơi ta thuộc về.</p><div class="hero-buttons"><a class="btn" href="#/movie/tang-may?booking=1">${ic('ticket')} Đặt vé ngay</a><button class="btn btn-glass" data-action="trailer" data-id="tang-may">${ic('play')} Xem trailer</button></div><span class="hero-footnote">Hình ảnh và câu chuyện sáng tạo cho bản minh họa</span></div><div class="hero-side"><span class="vertical-text">EVERY FRAME. A NEW WORLD.</span><span class="hero-index"><strong>01</strong> / 04</span></div></div></section><div class="container quick-wrap">${quickBook()}</div><section class="container section"><div class="section-heading"><div class="home-tabs" role="tablist" aria-label="Danh sách phim"><button role="tab" id="home-now" aria-selected="true" data-action="home-tab" data-tab="now">Đang chiếu<span>06</span></button><button role="tab" id="home-soon" aria-selected="false" data-action="home-tab" data-tab="soon">Sắp chiếu<span>02</span></button></div><a class="text-link" href="#/movies">Tất cả phim ${ic('arrow')}</a></div><div id="home-movies" class="movie-grid">${D.movies.filter(m=>m.status==='now').slice(0,4).map(movieCard).join('')}</div></section><section class="section offers-section"><div class="container">${heading('THÊM NIỀM VUI CHO CUỘC HẸN','Một chút ưu đãi, thật nhiều cảm xúc','#/offers')}<div class="offer-grid">${D.offers.map(offerCard).join('')}</div></div></section><section class="container section"><div class="experience-feature"><div class="experience-visual"><span class="experience-orbit"></span><span class="experience-big">IMAX</span><span>ĐỪNG CHỈ XEM. HÃY ĐẮM CHÌM.</span></div><div class="experience-copy"><span class="eyebrow">KHÔNG GIAN CHO TỪNG CẢM XÚC</span><h2>Điện ảnh.<br>Theo cách của bạn.</h2><p>Từ màn hình IMAX choáng ngợp đến ghế ngả êm ái. Tìm không gian dành cho câu chuyện bạn muốn sống cùng.</p><div class="tags"><span>IMAX</span><span>4DX</span><span>ScreenX</span><span>Ghế ngả</span></div><a class="btn btn-dark" href="#/experiences">Khám phá trải nghiệm ${ic('arrow')}</a></div></div></section><section class="container section">${heading('MỘT CUỘC HẸN GẦN BẠN','Rạp của bạn, ở ngay đây','#/cinemas')}<div class="cinema-grid">${D.cinemas.filter(c=>c.city===state.city).map(cinemaCard).join('')}</div></section><section class="club-strip container"><div>${ic('star')}<span>LUMIÈRE CLUB</span></div><h2>Yêu phim. Tích điểm.<br>Nhận thêm điều hay.</h2><a class="btn btn-dark" href="#/membership">Khám phá quyền lợi ${ic('arrow')}</a></section>`}
function moviesPage(){const tab=query.get('tab')==='soon'?'soon':'now';return `<div class="container page">${title('THẾ GIỚI TRÊN MÀN ẢNH','Tìm câu chuyện của bạn','Một bộ phim hay có thể bắt đầu một ngày thật khác.')}<div class="tabs"><a class="${tab==='now'?'active':''}" href="#/movies?tab=now">Đang chiếu</a><a class="${tab==='soon'?'active':''}" href="#/movies?tab=soon">Sắp chiếu</a></div><form class="filter-bar" id="movie-filters"><label class="search-field">${ic('search')}<span class="sr-only">Tên phim</span><input name="search" type="search" placeholder="Tìm tên phim…"></label><label><span class="sr-only">Thể loại</span><select name="genre"><option value="">Mọi thể loại</option>${[...new Set(D.movies.map(m=>m.genre))].map(g=>`<option>${g}</option>`).join('')}</select></label><label><span class="sr-only">Định dạng</span><select name="format"><option value="">Mọi định dạng</option><option>2D</option><option>3D</option></select></label><label><span class="sr-only">Phân loại độ tuổi</span><select name="age"><option value="">Mọi độ tuổi</option>${['P','K','T13','T16','T18'].map(a=>`<option>${a}</option>`).join('')}</select></label></form><p id="movie-count" class="muted"></p><div id="movie-results" class="movie-grid">${D.movies.filter(m=>m.status===tab).map(movieCard).join('')}</div><div class="notice">${ic('info')} P: mọi độ tuổi · K: dưới 13 tuổi cần người giám hộ · T13/T16/T18: từ 13/16/18 tuổi.</div></div>`}
function datePicker(selected,base,extra=''){return `<div class="date-picker" aria-label="Ngày xem">${D.days.map((d,i)=>`<a class="date-item ${selected===d?'selected':''}" href="${base}${base.includes('?')?'&':'?'}date=${d}${extra}"><span>${i===0?'Hôm nay':i===1?'Ngày mai':dateLabel(d,{weekday:'short'})}</span><strong>${dateLabel(d,{day:'2-digit',month:'2-digit'})}</strong></a>`).join('')}</div>`}
const statusLabels={available:'Còn vé',low:'Gần hết chỗ',sold:'Hết chỗ',stopped:'Ngừng bán'};
function showButton(s){const st=D.showStatus(s),room=D.roomOf(s),disabled=['sold','stopped'].includes(st);return `<button class="showtime ${st}" data-action="select-show" data-id="${s.id}" ${disabled?'disabled':''} aria-label="${s.time}, ${s.format}, ${s.language}, ${room.type}, ${statusLabels[st]}"><strong>${s.time}</strong><span>${s.format} · ${s.language}</span><small>${room.type} · ${statusLabels[st]}</small></button>`}
function showGroups(items,group='cinema'){if(!items.length)return empty('Chưa có suất chiếu phù hợp','Bạn có thể đổi ngày, rạp hoặc phiên bản để tìm suất khác.','Xem lịch chiếu khác','#/schedule');let ids=[...new Set(items.map(s=>group==='cinema'?s.cinemaId:s.movieId))];return ids.map(id=>{const entity=group==='cinema'?cinema(id):movie(id),ss=items.filter(s=>(group==='cinema'?s.cinemaId:s.movieId)===id);return `<article class="show-group">${group==='movie'?`<a class="schedule-mini-poster" href="#/movie/${id}">${img(entity.art,entity.title)}</a>`:''}<div class="show-group-body"><div class="show-group-heading"><h3><a href="#/${group}/${id}">${group==='cinema'?esc(entity.name):badge(entity)+' '+esc(entity.title)}</a></h3><span>${group==='cinema'?esc(entity.district)+' · '+esc(entity.city):entity.duration+' phút · '+entity.genre}</span></div>${group==='cinema'?`<p class="muted small">${esc(entity.address)}</p>`:''}<div class="showtime-list">${ss.map(showButton).join('')}</div></div></article>`}).join('')}
function movieDetail(id){const m=movie(id);if(!m)return notFound();const date=D.days.includes(query.get('date'))?query.get('date'):D.days[0],cid=D.cinemas.some(c=>c.id===query.get('cinema')&&c.city===state.city)?query.get('cinema'):'',format=m.formats.includes(query.get('format'))?query.get('format'):'';const ss=D.showtimes.filter(s=>s.movieId===id&&s.date===date&&(cid?s.cinemaId===cid:cinema(s.cinemaId).city===state.city)&&(!format||s.format===format));return `<section class="movie-detail-hero" style="--film-color:${m.accent}"><div class="container movie-detail-layout">${img(m.art,'Poster '+m.title,'detail-poster')}<div><a class="back-link" href="#/movies">Phim / ${m.status==='now'?'Đang chiếu':'Sắp chiếu'}</a><span class="eyebrow">${m.en}</span><h1>${m.title}</h1><div class="detail-meta">${badge(m)}<span>${m.duration} phút</span><span>${m.genre}</span><span>${m.country}</span></div><p class="detail-tagline">${m.blurb}</p><p>${m.description}</p><dl class="film-info"><div><dt>Khởi chiếu${m.status==='soon'?' dự kiến':''}</dt><dd>${dateLabel(m.release)}</dd></div><div><dt>Đạo diễn</dt><dd>${m.director}</dd></div><div><dt>Diễn viên</dt><dd>${m.cast}</dd></div><div><dt>Phiên bản ${m.status==='soon'?'dự kiến':'đang có'}</dt><dd>${m.formats.join(', ')} · ${m.languages.join(', ')}</dd></div></dl><button class="btn btn-dark" data-action="trailer" data-id="${m.id}">${ic('play')} Xem trailer minh họa</button><p class="small muted">${m.age==='P'?'Phù hợp mọi độ tuổi.':m.age==='K'?'Khán giả dưới 13 tuổi cần người giám hộ đi cùng.':`Chỉ dành cho khán giả từ ${m.age.slice(1)} tuổi trở lên. Mang theo giấy tờ khi được yêu cầu.`}</p></div></div></section><section class="container section" id="showtimes">${heading('CHỌN MỘT CUỘC HẸN','Lịch chiếu')}${m.status==='soon'?empty('Chưa mở bán','Phim dự kiến khởi chiếu '+dateLabel(m.release)+'. Chúng tôi chưa công bố suất chiếu.','Khám phá phim đang chiếu','#/movies'): `${datePicker(date,'#/movie/'+id,cid?'&cinema='+cid:'')}<form id="detail-filters" class="filter-bar" data-movie="${id}" data-date="${date}"><label><span>Rạp chiếu</span><select name="cinema"><option value="">Tất cả rạp tại ${esc(state.city)}</option>${D.cinemas.filter(c=>c.city===state.city).map(c=>`<option value="${c.id}" ${cid===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label><span>Định dạng phim</span><select name="format"><option value="">Tất cả định dạng</option>${m.formats.map(f=>`<option ${format===f?'selected':''}>${f}</option>`).join('')}</select></label><button class="btn btn-dark">Lọc lịch chiếu</button></form><p class="small muted">Giờ địa phương của rạp (UTC+7). Mỗi suất ghi rõ định dạng, ngôn ngữ và loại phòng.</p>${showGroups(ss)}`}</section>`}
function schedulePage(){const mode=query.get('mode')==='cinema'?'cinema':'movie',date=D.days.includes(query.get('date'))?query.get('date'):D.days[0],mid=D.movies.some(m=>m.id===query.get('movie'))?query.get('movie'):'tang-may',cs=D.cinemas.filter(c=>c.city===state.city),cid=cs.some(c=>c.id===query.get('cinema'))?query.get('cinema'):cs[0].id;const offer=D.offers.find(o=>o.id===query.get('offer')),offerQuery=offer?'&offer='+offer.id:'';const ss=D.showtimes.filter(s=>s.date===date&&(mode==='movie'?s.movieId===mid&&cinema(s.cinemaId).city===state.city:s.cinemaId===cid)&&(!offer||(offer.cinemas.includes(s.cinemaId)&&(!offer.rooms||offer.rooms.includes(D.roomOf(s).type)))));return `<div class="container page">${title('DÀNH THỜI GIAN CHO ĐIỀU BẠN THÍCH','Hôm nay, xem gì?','Lịch chiếu tại '+esc(state.city)+' · Giờ Việt Nam (UTC+7)')}<div class="tabs"><a class="${mode==='movie'?'active':''}" href="#/schedule?mode=movie">Theo phim</a><a class="${mode==='cinema'?'active':''}" href="#/schedule?mode=cinema">Theo rạp</a></div><form id="schedule-filter" data-mode="${mode}" data-offer="${offer?.id||''}" class="filter-bar"><label class="grow"><span>${mode==='movie'?'Phim muốn xem':'Rạp của bạn'}</span><select name="${mode}">${(mode==='movie'?D.movies:cs).map(x=>`<option value="${x.id}" ${x.id===(mode==='movie'?mid:cid)?'selected':''}>${esc(x.title||x.name)}${x.status==='soon'?' · Sắp chiếu':''}</option>`).join('')}</select></label><input type="hidden" name="date" value="${date}"><button class="btn btn-dark">Xem lịch ${ic('arrow')}</button></form>${offer?`<div class="notice">${ic('info')} Suất phù hợp ưu đãi ${offer.code}: ${offer.rules}</div>`:''}${datePicker(date,`#/schedule?mode=${mode}&${mode}=${mode==='movie'?mid:cid}${offerQuery}`)}<div class="legend-status"><span>● Còn vé</span><span>◐ Gần hết chỗ</span><span>× Hết chỗ</span><span>— Ngừng bán</span></div>${showGroups(ss,mode==='movie'?'cinema':'movie')}</div>`}
function cinemasPage(){return `<div class="container page">${title('GẦN BẠN HƠN MỘT CHÚT','Một không gian, ngàn câu chuyện','Khám phá 3 cụm rạp Lumière tại TP. Hồ Chí Minh và Hà Nội.')}<form id="cinema-filters" class="filter-bar"><label class="search-field grow">${ic('search')}<span class="sr-only">Tìm rạp</span><input name="search" type="search" placeholder="Tìm theo tên rạp hoặc địa chỉ…"></label><label><span class="sr-only">Tỉnh thành</span><select name="city"><option value="">Tất cả tỉnh thành</option>${['TP. Hồ Chí Minh','Hà Nội'].map(c=>`<option ${c===state.city?'selected':''}>${c}</option>`).join('')}</select></label></form><div id="cinema-results" class="cinema-grid">${D.cinemas.filter(c=>c.city===state.city).map(cinemaCard).join('')}</div><p class="small muted">Địa chỉ và hình ảnh rạp là dữ liệu minh họa. Liên kết bản đồ chỉ tìm theo địa chỉ này.</p></div>`}
function cinemaDetail(id){const c=cinema(id);if(!c)return notFound();const date=D.days.includes(query.get('date'))?query.get('date'):D.days[0];return `<div class="cinema-cover">${img(c.id,'Kiến trúc minh họa '+c.name)}</div><div class="container page cinema-detail">${title(esc(c.city)+' / '+esc(c.district),esc(c.name),esc(c.address),`<a class="btn btn-dark" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.address)}">${ic('pin')} Mở bản đồ</a>`)}<div class="cinema-info-grid"><article class="panel"><h3>Đến rạp thật dễ</h3><p>${c.directions}</p><p><strong>Mở cửa:</strong> ${c.hours} (UTC+7)<br><strong>Liên hệ minh họa:</strong> ${c.phone}</p><div class="tags">${c.amenities.map(a=>`<span>${a}</span>`).join('')}</div></article><article class="panel"><h3>Trải nghiệm tại đây</h3>${[...new Set(c.rooms.map(r=>r.type))].map(t=>`<p><strong>${t}</strong> — ${D.experiences.find(e=>e.name===t).text}</p>`).join('')}</article></div><section class="section">${heading('LỊCH CHIẾU TẠI RẠP','Chọn phim cho cuộc hẹn')}${datePicker(date,'#/cinema/'+id)}${showGroups(D.showtimes.filter(s=>s.cinemaId===id&&s.date===date),'movie')}</section></div>`}
function experiencesPage(){return `<div class="container page">${title('ĐẮM CHÌM VÀO TỪNG KHOẢNH KHẮC','Trải nghiệm Lumière','Loại phòng khác với định dạng 2D/3D và hạng ghế. Mỗi suất ghi rõ các lựa chọn hỗ trợ.')}<div class="experience-grid">${D.experiences.map((e,i)=>`<article class="panel experience-tile"><span class="experience-number">0${i+1}</span><h2>${e.name}</h2><p>${e.text}</p><div class="tags">${D.cinemas.filter(c=>c.rooms.some(r=>r.type===e.name)).map(c=>`<a href="#/cinema/${c.id}">${c.name}</a>`).join('')}</div></article>`).join('')}</div></div>`}
function searchPage(){const term=query.get('q')||'',q=term.toLocaleLowerCase('vi');const ms=term?D.movies.filter(m=>m.title.toLocaleLowerCase('vi').includes(q)):[],cs=term?D.cinemas.filter(c=>(c.name+' '+c.city+' '+c.district).toLocaleLowerCase('vi').includes(q)):[];return `<div class="container page">${title('BẠN ĐANG TÌM…','Một bộ phim hay, một rạp gần?')}<form id="global-search" class="filter-bar"><label class="search-field grow">${ic('search')}<span class="sr-only">Từ khóa phim hoặc rạp</span><input name="q" type="search" required value="${esc(term)}" placeholder="Nhập tên phim, rạp hoặc khu vực" autofocus></label><button class="btn">Tìm kiếm</button></form>${!term?'<p class="muted">Gợi ý: Mùa hè, Riverside, Hà Nội.</p>':`<p role="status">${ms.length+cs.length} kết quả cho “${esc(term)}”</p>${ms.length?'<h2>Phim</h2><div class="movie-grid">'+ms.map(movieCard).join('')+'</div>':''}${cs.length?'<h2 class="section-gap">Rạp chiếu</h2><div class="cinema-grid">'+cs.map(cinemaCard).join('')+'</div>':''}${!ms.length&&!cs.length?empty('Chưa tìm thấy kết quả','Thử từ khóa ngắn hơn hoặc khám phá lịch chiếu.'):''}`}</div>`}
// Reservations are local to this browser. A separate key coordinates open tabs.
function holdMap(){const map=read(HOLD_KEY,{});for(const sid in map){for(const id in map[sid])if(map[sid][id].until<=Date.now())delete map[sid][id];if(!Object.keys(map[sid]).length)delete map[sid]}return map}
function releaseBy(sid,heldBy=owner){const map=holdMap();for(const id in map[sid]||{})if(map[sid][id].owner===heldBy)delete map[sid][id];write(HOLD_KEY,map)}
function releaseSeats(){if(state.booking)releaseBy(state.booking.showId)}
function soldLocally(sid,id){return state.orders.some(o=>o.status==='paid'&&o.show.id===sid&&o.seats.some(s=>s.id===id))}
function startBooking(id){const pending=state.orders.find(o=>o.sourceBooking===id&&['processing','unknown'].includes(o.status));if(pending){grantOrder(pending.code);toast('Đơn này đang chờ kết quả. Kiểm tra đơn trước khi đặt lại.');go('#/result/'+pending.code);return}const s=show(id);if(!s||['sold','stopped'].includes(D.showStatus(s)))return toast('Suất này đã ngừng bán hoặc hết chỗ. Vui lòng chọn suất khác.');if(state.booking?.showId===id&&state.booking.expiresAt>Date.now()){go('#/booking/seats');return}releaseSeats();state.booking={showId:id,seats:[],foods:{},expiresAt:Date.now()+600000,expired:false,promo:'',contact:state.user?{name:state.user.name,email:state.user.email,phone:state.user.phone||''}:{name:'',email:'',phone:''},method:'Ví điện tử',scenario:'success'};save();go('#/booking/seats')}
function bookingContext(){const b=state.booking,s=b&&show(b.showId);if(!s)return null;return {b,s,m:movie(s.movieId),c:cinema(s.cinemaId),r:D.roomOf(s)}}
function selectedSeats(){const x=bookingContext();if(!x)return [];return x.b.seats.map(p=>{const seat=D.seatsFor(x.s).find(s=>s.id===p.id);return seat?{...seat,category:p.category,price:D.price(x.s,seat,p.category)}:null}).filter(Boolean)}
function selectedFoods(){const x=bookingContext();if(!x)return [];return D.products.filter(p=>p.cinemas.includes(x.c.id)&&x.b.foods[p.id]>0).map(p=>({...p,quantity:x.b.foods[p.id]}))}
function totals(){const seats=selectedSeats(),foods=selectedFoods(),ticket=seats.reduce((a,s)=>a+s.price,0),food=foods.reduce((a,p)=>a+p.price*p.quantity,0),discount=promoResult(state.booking?.promo,ticket,food).discount;return {ticket,food,discount,total:ticket+food-discount}}
function promoResult(code,ticket,food){if(!code)return {discount:0};const x=bookingContext(),o=D.offers.find(o=>o.code===code);if(!o||o.kind==='member')return {discount:0,error:'Mã không hợp lệ. Thử CHAO20 hoặc BAP20 và xem điều kiện.'};if(!o.cinemas.includes(x.c.id))return {discount:0,error:'Mã không áp dụng tại cụm rạp này.'};if(o.id==='first'){
if(!o.rooms.includes(x.r.type))return {discount:0,error:'CHAO20 chỉ áp dụng phòng Tiêu chuẩn.'};
if(selectedSeats().some(s=>s.category!=='Người lớn'))return {discount:0,error:'CHAO20 không áp dụng cùng vé ưu đãi theo đối tượng.'};
if(ticket<o.minimum)return {discount:0,error:'CHAO20 cần tiền vé từ 100.000đ.'};
const contact=x.b.contact?.email?.trim().toLowerCase();if(!contact)return {discount:0,error:'Nhập email nhận vé trước khi áp dụng CHAO20.'};
if(state.orders.some(ord=>['paid','processing','unknown'].includes(ord.status)&&ord.promo===code&&ord.contact.email.toLowerCase()===contact))return {discount:0,error:'Email này đã dùng hoặc đang có đơn chờ xử lý với mã CHAO20.'};
return {discount:Math.min(o.max,Math.round(ticket*o.percent))};}
if(food<o.minimum)return {discount:0,error:'BAP20 cần giá trị đồ ăn từ 100.000đ.'};return {discount:o.amount};}
function validateReservation(){const x=bookingContext();if(!x)return 'Chưa chọn suất chiếu.';if(x.b.expired||x.b.expiresAt<=Date.now())return 'Đã hết thời gian giữ chỗ. Vui lòng chọn lại ghế.';if(['sold','stopped'].includes(D.showStatus(x.s)))return 'Suất chiếu đã ngừng bán. Vui lòng chọn suất khác.';if(!x.b.seats.length)return 'Bạn cần chọn ít nhất một đơn vị ghế.';const map=holdMap();for(const seat of selectedSeats()){if(seat.state!=='free'||soldLocally(x.s.id,seat.id))return 'Ghế '+seat.id+' không còn trống. Vui lòng chọn lại.';const h=map[x.s.id]?.[seat.id];if(!h||h.owner!==owner)return 'Lượt giữ ghế đã thay đổi ở cửa sổ khác. Vui lòng chọn lại.';}return null}
function bookingProgress(step){return `<ol class="booking-progress" aria-label="Tiến trình đặt vé">${[['seats','Chọn ghế'],['food','Bắp & nước'],['checkout','Thanh toán'],['result','Nhận vé']].map(([p,t],i)=>`<li class="${i===step?'current':i<step?'done':''}" ${i===step?'aria-current="step"':''}>${i<step&&i<3?`<a href="#/booking/${p}"><span>${ic('check')}</span>${t}</a>`:`<span>${i+1}</span>${t}`}</li>`).join('')}</ol>`}
function bookingSummary(button='',label=''){const x=bookingContext(),t=totals(),seats=selectedSeats();return `<aside class="order-summary"><div class="summary-title"><span>CUỘC HẸN CỦA BẠN</span>${ic('ticket')}</div><div class="summary-film">${img(x.m.art,x.m.title)}<div>${badge(x.m)}<h3>${x.m.title}</h3><p>${x.m.duration} phút · ${x.s.format}<br>${x.s.language}</p></div></div><div class="summary-location"><strong>${x.c.name}</strong><p>${x.r.name} · ${x.r.type}</p><p><strong>${x.s.time}</strong> · ${dateLabel(x.s.date,{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'})}</p></div><div class="summary-seats"><span>Ghế đã chọn</span><strong>${seats.length?seats.map(s=>s.id).join(', '):'Chưa chọn ghế'}</strong>${seats.length?`<small>${seats.length} đơn vị · ${seats.reduce((a,s)=>a+s.people,0)} khách</small>`:''}</div><dl class="price-breakdown"><div><dt>Tiền vé</dt><dd>${money(t.ticket)}</dd></div><div><dt>Bắp & nước</dt><dd>${money(t.food)}</dd></div><div class="discount"><dt>Giảm giá</dt><dd>−${money(t.discount)}</dd></div><div class="total"><dt>Tổng thanh toán</dt><dd>${money(t.total)}</dd></div></dl>${button?`<button class="btn full" data-action="${button}" ${!seats.length||x.b.expired?'disabled':''}>${label}${ic('arrow')}</button>`:''}<p class="small muted summary-note">Giá cuối cùng, đã gồm thuế. Mô phỏng, không thu tiền thật.</p><div class="hold-clock">${ic('clock')}<span>Giữ chỗ còn <strong data-countdown>10:00</strong></span></div></aside>`}
function mobileRecap(step){const x=bookingContext(),t=totals();return `<div class="mobile-booking-recap"><div><strong>${x.m.title}</strong><span>${x.c.name} · ${x.s.time}, ${dateLabel(x.s.date,{day:'2-digit',month:'2-digit'})}</span><span>Ghế: ${x.b.seats.map(s=>s.id).join(', ')||'Chưa chọn'}</span><button class="text-link" data-action="summary">Xem tóm tắt</button></div><div><strong>${money(t.total)}</strong><button class="btn btn-small" data-action="${step==='seats'?'to-food':step==='food'?'to-checkout':'summary'}" ${x.b.expired||!x.b.seats.length?'disabled':''}>${step==='checkout'?'Xem tổng tiền':'Tiếp tục'}</button></div></div>`}
function expiredBanner(){const x=bookingContext();return x.b.expired?`<div class="alert error" role="alert"><strong>Thời gian giữ chỗ đã kết thúc.</strong><p>Ghế đã được giải phóng. Chọn lại ghế để tiếp tục; đồ ăn và thông tin liên hệ vẫn được giữ.</p><button class="btn btn-dark" data-action="restart">Chọn lại ghế</button></div>`:''}
function bookingPage(step){const x=bookingContext();if(!x)return `<div class="container page">${empty('Cuộc hẹn đang chờ bạn','Hãy chọn phim và suất chiếu trước khi đặt ghế.')}</div>`;if(!['seats','food','checkout'].includes(step))return notFound();const pending=state.orders.find(o=>o.sourceBooking===x.b.showId&&['processing','unknown'].includes(o.status));if(pending)return `<div class="container page">${empty('Đơn của bạn đang chờ kết quả','Kiểm tra trạng thái đơn trước khi thay đổi ghế hoặc thanh toán lại.','Kiểm tra đơn','#/result/'+pending.code)}</div>`;const n=['seats','food','checkout'].indexOf(step);return `<div class="container booking-page">${bookingProgress(n)}${expiredBanner()}<div class="booking-layout"><div class="booking-main">${step==='seats'?seatPage(x):step==='food'?foodPage(x):checkoutPage(x)}</div>${bookingSummary(step==='seats'?'to-food':step==='food'?'to-checkout':'',step==='seats'?'Tiếp tục · Bắp & nước':'Tiếp tục · Thanh toán')}</div><details class="demo-controls"><summary>Công cụ minh họa: kiểm tra hết thời gian giữ chỗ</summary><p>Chỉ ảnh hưởng lượt đặt vé hiện tại.</p><button class="btn btn-outline" data-action="expire">Kết thúc giữ chỗ ngay</button></details>${mobileRecap(step)}</div>`}
function seatPage(x){const seats=D.seatsFor(x.s),map=holdMap(),rows=[...new Set(seats.map(s=>s.row))],cats=D.categories(x.s);return `${title('BƯỚC 01','Chọn góc nhìn của bạn','Chọn tối đa 8 khách. Ghế đôi và giường được bán nguyên đơn vị.')}<div class="seat-toolbar"><span>${ic('seat')} ${x.r.name} · ${x.r.type}</span><button class="btn btn-small btn-outline" data-action="zoom">Phóng to sơ đồ</button></div><div class="seat-map-scroll" tabindex="0" role="region" aria-label="Sơ đồ ghế. Cuộn ngang hoặc dùng nút phóng to."><div class="seat-map ${x.r.layout}"><div class="screen"><span>MÀN HÌNH</span></div><div class="seats-grid">${rows.map(row=>`<div class="seat-row"><span class="row-label">${row}</span>${seats.filter(s=>s.row===row).map((seat,i,arr)=>{const selected=x.b.seats.some(s=>s.id===seat.id),external=map[x.s.id]?.[seat.id],status=soldLocally(x.s.id,seat.id)?'sold':external&&external.owner!==owner?'held':seat.state,blocked=status!=='free';return `${i===Math.ceil(arr.length/2)?'<span class="seat-aisle" aria-hidden="true"></span>':''}<button class="seat ${seat.type==='VIP'?'vip':''} ${seat.people===2?'paired':''} ${x.r.layout==='bed'?'bed-seat':''} ${selected?'selected':status}" data-action="seat" data-id="${seat.id}" aria-label="Ghế ${seat.id}, ${seat.type}, ${selected?'đang chọn':status==='free'?'còn trống':status==='sold'?'đã bán':status==='held'?'đang được giữ':'không sử dụng'}, ${money(D.price(x.s,seat))} mỗi ${seat.unit}" aria-pressed="${selected}" ${blocked||x.b.expired?'disabled':''}>${seat.num}</button>`}).join('')}<span class="row-label">${row}</span></div>`).join('')}</div><div class="seat-exit">LỐI VÀO / RA</div></div></div><div class="seat-legend">${[['free','Còn trống'],['selected','Đang chọn'],['held','Đang được giữ'],['sold','Đã bán'],['disabled','Không sử dụng']].map(([s,t])=>`<span><i class="seat-key ${s}"></i>${t}</span>`).join('')}</div><div class="seat-prices">${[...new Set(seats.map(s=>s.type))].map(type=>{const seat=seats.find(s=>s.type===type);return `<span><i class="type-key ${type==='VIP'?'vip':seat.people===2?'pair':''}"></i><strong>${type}</strong> ${money(D.price(x.s,seat))}/${seat.unit}</span>`}).join('')}</div><div class="selected-ticket-list"><h3>Vé của bạn</h3>${selectedSeats().length?selectedSeats().map(s=>`<div class="ticket-selection"><div><strong>${s.id}</strong><span>${s.type} · ${s.people} khách/${s.unit}</span></div><label><span class="sr-only">Đối tượng vé ghế ${s.id}</span><select data-category="${s.id}" ${s.people===2?'disabled':''}>${(s.people===2?['Người lớn']:cats).map(c=>`<option ${s.category===c?'selected':''}>${c}</option>`).join('')}</select></label><strong>${money(s.price)}/${s.unit}</strong></div>`).join(''):'<p class="muted">Chạm vào ghế còn trống trên sơ đồ để chọn.</p>'}</div><div class="notice">${ic('info')}<div><strong>Điều kiện vé theo đối tượng</strong><p>Trẻ em: dưới 12 tuổi và cao dưới 1,3 m; chỉ phim P/K, phim K cần giám hộ. Học sinh – sinh viên: xuất trình thẻ còn hiệu lực. Người cao tuổi: từ 60 tuổi, có giấy tờ. Ghế đôi/giường bán nguyên đơn vị cho 2 khách, không giảm theo đối tượng. Phòng Cao cấp và Giường nằm không áp dụng giá theo đối tượng.</p><p>${x.m.age==='P'?'Phim dành cho mọi độ tuổi.':x.m.age==='K'?'Phim K: khách dưới 13 tuổi cần giám hộ.':'Phim '+x.m.age+': chỉ dành cho khách từ '+x.m.age.slice(1)+' tuổi.'} ${x.r.type==='4DX'?'4DX không phù hợp trẻ dưới 1 m và người nhạy cảm với chuyển động.':''}</p></div></div><a class="back-link" href="#/movie/${x.m.id}?date=${x.s.date}&cinema=${x.c.id}">← Đổi suất chiếu</a>`}
function foodPage(x){return `${title('BƯỚC 02','Thêm chút giòn, thêm chút vui','Bắp và nước được phục vụ tại '+esc(x.c.name)+'. Có thể bỏ qua bước này.')}<div class="product-list">${D.products.filter(p=>p.cinemas.includes(x.c.id)).map(p=>`<article class="product-card">${img(p.art,p.name)}<div><h3>${p.name}</h3><p>${p.contents}</p><strong>${money(p.price)}</strong></div><div class="quantity" aria-label="Số lượng ${p.name}"><button data-action="food" data-id="${p.id}" data-delta="-1" aria-label="Giảm ${p.name}" ${!(x.b.foods[p.id]>0)||x.b.expired?'disabled':''}>${ic('minus')}</button><output aria-label="Số lượng">${x.b.foods[p.id]||0}</output><button data-action="food" data-id="${p.id}" data-delta="1" aria-label="Thêm ${p.name}" ${(x.b.foods[p.id]||0)>=10||x.b.expired?'disabled':''}>${ic('plus')}</button></div></article>`).join('')}</div><div class="space-between"><a class="back-link" href="#/booking/seats">← Quay lại chọn ghế</a><button class="text-link" data-action="to-checkout">Tiếp tục với lựa chọn hiện tại ${ic('arrow')}</button></div><p class="small muted">Thông báo dị ứng: bắp có thể chứa sữa, đậu nành. Hỏi nhân viên khi nhận món.</p>`}
function contactFields(c,prefix=''){return `<div class="form-grid"><label class="full-field">Họ và tên <input name="${prefix}name" autocomplete="name" value="${esc(c.name)}" required minlength="2" maxlength="80"></label><label>Email nhận vé <input name="${prefix}email" type="email" autocomplete="email" value="${esc(c.email)}" required maxlength="120"></label><label>Số điện thoại <input name="${prefix}phone" type="tel" autocomplete="tel" value="${esc(c.phone)}" required pattern="0[0-9]{9}" placeholder="10 chữ số, bắt đầu bằng 0"></label></div>`}
function checkoutPage(x){const t=totals(),promo=promoResult(x.b.promo,t.ticket,t.food);return `${title('BƯỚC 03','Kiểm tra để an tâm tận hưởng','Vui lòng kiểm tra suất chiếu và thông tin nhận vé trước khi tiếp tục.')}<div class="panel checkout-items"><h3>Thông tin đặt vé</h3>${selectedSeats().map(s=>`<div class="line-item"><span>Ghế ${s.id} · ${s.type}<small>${s.category} · ${s.people} khách/${s.unit}</small></span><strong>${money(s.price)}</strong></div>`).join('')}${selectedFoods().map(p=>`<div class="line-item"><span>${p.quantity} × ${p.name}<small>${p.contents}</small></span><strong>${money(p.price*p.quantity)}</strong></div>`).join('')}<a class="text-link" href="#/booking/seats">Sửa ghế</a> · <a class="text-link" href="#/booking/food">Sửa bắp & nước</a></div>${!state.user?`<div class="member-nudge">${ic('star')}<div>Đặt vé không cần tài khoản.<br><button class="text-link" data-action="login-return">Đăng nhập để tích điểm và lưu vé dễ hơn ${ic('arrow')}</button></div></div>`:''}<form id="checkout-form" novalidate><div class="panel"><h3>Người nhận vé</h3>${contactFields(x.b.contact)}<p class="field-error" id="contact-error" role="alert"></p></div><div class="panel"><h3>Mã ưu đãi</h3><div class="promo-input"><label class="grow"><span class="sr-only">Mã ưu đãi</span><input name="promo" placeholder="Nhập mã ưu đãi" value="${esc(x.b.promo)}" maxlength="30"></label><button class="btn btn-outline" type="button" data-action="apply-promo">Áp dụng</button></div>${x.b.promo?`<p class="${promo.error?'field-error':'success-text'}" role="status">${esc(promo.error||'Đã áp dụng '+x.b.promo+': giảm '+money(promo.discount))}</p><button type="button" class="text-link" data-action="remove-promo">Bỏ mã</button>`:''}<details><summary>Điều kiện CHAO20 và BAP20</summary><p><strong>CHAO20:</strong> ${D.offers[0].rules}</p><p><strong>BAP20:</strong> ${D.offers[1].rules}</p><p>Hiệu lực trong 7 ngày lịch chiếu của bộ dữ liệu mẫu: ${dateLabel(D.days[0])} – ${dateLabel(D.days[6])}.</p></details></div><div class="panel"><h3>Phương thức thanh toán</h3><div class="payment-options">${['Ví điện tử','Thẻ nội địa','Thẻ quốc tế'].map((v,i)=>`<label class="radio-card"><input type="radio" name="method" value="${v}" ${x.b.method===v?'checked':''}>${ic(i===0?'ticket':'user')}<span>${v}<small>Giao dịch giả lập, không nhập thông tin thẻ</small></span></label>`).join('')}</div></div><details class="demo-controls" open><summary>Mô phỏng kết quả thanh toán</summary><p>Chọn tình huống để kiểm tra giao diện. Không kết nối cổng thanh toán.</p><label>Kết quả sau xử lý<select name="scenario">${[['success','Thành công'],['failed','Thất bại'],['timeout','Hết thời gian'],['unknown','Chưa xác định kết quả']].map(([v,t])=>`<option value="${v}" ${x.b.scenario===v?'selected':''}>${t}</option>`).join('')}</select></label></details><label class="checkbox-line"><input name="terms" type="checkbox" required><span>Tôi xác nhận phim, suất, ghế, điều kiện độ tuổi và đồng ý với <a href="#/policy/purchase">điều kiện mua vé</a>, <a href="#/policy/terms">điều khoản sử dụng</a>.</span></label><p id="checkout-error" class="field-error" role="alert"></p><button type="submit" class="btn full payment-submit" ${x.b.expired||paymentBusy?'disabled':''}>${ic('ticket')} Thanh toán mô phỏng · ${money(t.total)}</button><p class="small muted">Đây là bản minh họa. Không yêu cầu thông tin thẻ, OTP ngân hàng hoặc tiền thật.</p></form><a class="back-link" href="#/booking/food">← Quay lại bắp & nước</a>`}
function syncContact(form){const x=bookingContext();if(!x)return;['name','email','phone'].forEach(k=>{if(form.elements[k])x.b.contact[k]=form.elements[k].value.trim()});if(form.elements.method)x.b.method=form.elements.method.value;if(form.elements.scenario)x.b.scenario=form.elements.scenario.value;save()}
function contactError(c){if(c.name.length<2)return 'Họ và tên cần ít nhất 2 ký tự.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email))return 'Email nhận vé chưa đúng định dạng.';if(!/^0\d{9}$/.test(c.phone))return 'Số điện thoại cần 10 chữ số và bắt đầu bằng 0.';return null}
function toggleSeat(id){const x=bookingContext();if(!x||x.b.expired)return;const seat=D.seatsFor(x.s).find(s=>s.id===id);if(!seat||seat.state!=='free'||soldLocally(x.s.id,id))return toast('Ghế không còn trống.');const map=holdMap();map[x.s.id]||={};if(map[x.s.id][id]&&map[x.s.id][id].owner!==owner)return toast('Ghế đang được giữ trong cửa sổ khác.');const pos=x.b.seats.findIndex(s=>s.id===id);if(pos>=0){x.b.seats.splice(pos,1);delete map[x.s.id][id]}else{if(selectedSeats().reduce((a,s)=>a+s.people,0)+seat.people>8)return toast('Mỗi đơn tối đa 8 khách. Ghế đôi và giường tính 2 khách.');x.b.seats.push({id,category:'Người lớn'});map[x.s.id][id]={owner,until:x.b.expiresAt}}write(HOLD_KEY,map);save();refreshBooking();toast((pos>=0?'Đã bỏ ghế ':'Đã chọn ghế ')+id+'. Tiền vé: '+money(totals().ticket))}
function refreshBooking(){const y=window.scrollY,el=document.activeElement;let key='';if(el?.dataset?.category)key='[data-category="'+el.dataset.category+'"]';else if(el?.dataset?.action&&el?.dataset?.id)key='[data-action="'+el.dataset.action+'"][data-id="'+el.dataset.id+'"]'+(el.dataset.delta?'[data-delta="'+el.dataset.delta+'"]':'');render(false);window.scrollTo(0,y);if(key)$(key)?.focus({preventScroll:true})}
function expireBooking(){if(!state.booking||state.booking.expired)return;releaseSeats();state.booking.expired=true;state.booking.seats=[];save();if(route.startsWith('/booking/'))render(false);toast('Đã hết thời gian giữ chỗ. Vui lòng chọn lại ghế.')}
function tick(){const x=bookingContext();if(!x)return;let sec=Math.max(0,Math.ceil((x.b.expiresAt-Date.now())/1000));$$('[data-countdown]').forEach(el=>{el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;el.closest('.hold-clock')?.classList.toggle('urgent',sec<120)});if(sec===0&&!x.b.expired&&!state.orders.some(o=>o.status==='processing'&&o.sourceBooking===x.b.showId))expireBooking()}
function pay(form){if(paymentBusy)return;const pending=state.orders.find(o=>o.sourceBooking===state.booking?.showId&&['processing','unknown'].includes(o.status));if(pending){grantOrder(pending.code);go('#/result/'+pending.code);return}syncContact(form);const x=bookingContext(),err=validateReservation()||contactError(x.b.contact);if(err){$('#checkout-error').textContent=err;$('#checkout-error').focus();return}if(!form.elements.terms.checked){$('#checkout-error').textContent='Vui lòng xác nhận thông tin và đồng ý điều kiện mua vé.';form.elements.terms.focus();return}const t=totals(),pr=promoResult(x.b.promo,t.ticket,t.food);if(pr.error){$('#checkout-error').textContent=pr.error+' Bỏ mã hoặc áp dụng mã phù hợp trước khi thanh toán.';return}paymentBusy=true;form.querySelector('[type=submit]').disabled=true;const code='LM-'+Date.now().toString(36).toUpperCase()+Math.random().toString(36).slice(2,5).toUpperCase();const o={code,sourceBooking:x.b.showId,holdOwner:owner,expiresAt:x.b.expiresAt,show:{...x.s},movie:{...x.m},cinema:{...x.c},room:{...x.r},seats:selectedSeats(),foods:selectedFoods(),ticketTotal:t.ticket,foodTotal:t.food,discount:t.discount,total:t.total,promo:x.b.promo,contact:{...x.b.contact},payment:x.b.method+' (mô phỏng)',status:'processing',used:false,userId:state.user?.id||null,createdAt:Date.now(),scenario:x.b.scenario,resolveAt:Date.now()+2200};state.orders.unshift(o);grantOrder(code);save();go('#/result/'+code);setTimeout(()=>resolvePayment(code),2300)}
function resolvePayment(code){const o=state.orders.find(o=>o.code===code);if(!o||o.status!=='processing')return;if(o.scenario==='success'&&o.expiresAt<=Date.now()){o.status='timeout'}else if(o.scenario==='success'&&o.seats.some(seat=>soldLocally(o.show.id,seat.id))){o.status='failed'}else{o.status=({success:'paid',failed:'failed',timeout:'timeout',unknown:'unknown'})[o.scenario]||'unknown'}paymentBusy=false;if(o.status==='paid'){releaseBy(o.sourceBooking,o.holdOwner);if(state.booking?.showId===o.sourceBooking)state.booking=null}else if(o.status==='timeout'){releaseBy(o.sourceBooking,o.holdOwner);if(state.booking?.showId===o.sourceBooking){state.booking.expired=true;state.booking.seats=[]}}save();if(route==='/result/'+code)render(false)}
function orderAllowed(o){if(!o)return false;if(state.user&&(o.userId===state.user.id||o.contact.email.toLowerCase()===state.user.email.toLowerCase()))return true;const grants=read('lumiere-guest-access',[]);return grants.includes(o.code)}
function grantOrder(code){const grants=read('lumiere-guest-access',[]);if(!grants.includes(code))grants.push(code);write('lumiere-guest-access',grants)}
function qr(code){let v=[...code].reduce((a,c)=>a+c.charCodeAt(0),0);const finder=(x,y)=>`<rect x="${x}" y="${y}" width="7" height="7"/><rect x="${x+1}" y="${y+1}" width="5" height="5" fill="white"/><rect x="${x+2}" y="${y+2}" width="3" height="3"/>`;let cells='';for(let y=0;y<25;y++)for(let x=0;x<25;x++){if((x<8&&y<8)||(x>16&&y<8)||(x<8&&y>16))continue;v=(v*1664525+1013904223)>>>0;if(v%3!==0)cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`}return `<svg class="qr" viewBox="-2 -2 29 29" role="img" aria-label="QR minh họa, không quét được và không có giá trị vào rạp"><rect x="-2" y="-2" width="29" height="29" fill="white"/><g fill="#172b2b">${cells}${finder(0,0)}${finder(18,0)}${finder(0,18)}</g></svg>`}
const paymentLabel={paid:'Đã thanh toán',failed:'Thanh toán thất bại',timeout:'Hết thời gian',unknown:'Chưa xác định',processing:'Đang xử lý'};
function ticket(o){const ended=new Date(o.show.date+'T'+o.show.time+':00+07:00').getTime()<Date.now();return `<article class="electronic-ticket" id="electronic-ticket"><div class="ticket-top"><span class="brand-text">lumière <small>CINEMA</small></span><span>VÉ ĐIỆN TỬ · MINH HỌA</span></div><div class="ticket-content">${img(o.movie.art,o.movie.title,'ticket-poster')}<div><div>${badge(o.movie)}<span class="status-pill paid">${paymentLabel[o.status]}</span></div><h2>${o.movie.title}</h2><p>${o.cinema.name}<br>${o.room.name} · ${o.room.type} · ${o.show.format} · ${o.show.language}</p><div class="ticket-facts"><div><small>Ngày xem</small><strong>${dateLabel(o.show.date)}</strong></div><div><small>Giờ chiếu · UTC+7</small><strong>${o.show.time}</strong></div><div><small>Ghế / đơn vị bán</small><strong>${o.seats.map(s=>s.id).join(', ')}</strong></div><div><small>Số khách</small><strong>${o.seats.reduce((a,s)=>a+s.people,0)}</strong></div></div><p class="small">Sử dụng vé: <strong>${o.used?'Đã sử dụng':ended?'Đã qua giờ chiếu':'Chưa sử dụng'}</strong></p></div><div class="ticket-qr">${qr(o.code)}<strong>${esc(o.code)}</strong><small>QR minh họa · Không có giá trị vào rạp</small></div></div><div class="ticket-bottom"><span>Vui lòng đến trước giờ chiếu 15 phút. Mang theo giấy tờ phù hợp độ tuổi và đối tượng vé.</span><strong>${money(o.total)}</strong></div></article>`}
function resultPage(code){const o=state.orders.find(o=>o.code===code);if(!o)return notFound();if(!orderAllowed(o))return `<div class="container page">${empty('Xác thực để xem đơn','Nhập mã đơn và email hoặc số điện thoại đã dùng để đặt vé.','Tra cứu đơn','#/lookup')}</div>`;if(o.status==='processing'&&o.resolveAt<Date.now()){setTimeout(()=>resolvePayment(code),0)}const content= o.status==='paid'?`<div class="result-intro"><span class="result-icon">${ic('check')}</span><span class="eyebrow">CUỘC HẸN ĐÃ SẴN SÀNG</span><h1>Hẹn bạn tại rạp!</h1><p>Thanh toán mô phỏng thành công. Vé đã được lưu trên trình duyệt này.<br>Không gửi email thật và không có giá trị sử dụng tại rạp.</p></div>${ticket(o)}${o.foods.length?`<div class="notice">${ic('info')}<div><strong>Đừng quên bắp và nước của bạn</strong><p>${o.foods.map(p=>p.quantity+' × '+p.name).join(' · ')}</p><p>Trong hành trình thực tế, xuất trình mã đơn tại quầy đồ ăn của ${o.cinema.name} để nhận trước khi vào phòng.</p></div></div>`:''}<div class="result-actions"><a class="btn" href="#/ticket/${o.code}">Xem vé ${ic('ticket')}</a><button class="btn btn-outline" data-action="print">${ic('print')} In vé</button><a class="text-link" href="#/">Về trang chủ ${ic('arrow')}</a></div>`:o.status==='processing'?`<div class="result-intro"><span class="spinner"></span><h1>Đang xử lý thanh toán</h1><p>Vui lòng chờ. Chưa có vé được phát hành cho đơn này.</p><p>Mã đơn: <strong>${o.code}</strong></p></div>`:`<div class="result-intro"><span class="result-icon warning">${ic('info')}</span><span class="eyebrow">MÃ ĐƠN ${o.code}</span><h1>${o.status==='unknown'?'Chưa xác định kết quả':o.status==='timeout'?'Đã hết thời gian thanh toán':'Thanh toán chưa thành công'}</h1><p>${o.status==='unknown'?'Chưa có xác nhận thanh toán. Kiểm tra trạng thái đơn trước khi thực hiện bất kỳ thanh toán nào khác. Không có vé được phát hành lúc này.':o.status==='timeout'?'Ghế đã được giải phóng. Hãy chọn lại ghế và tạo lượt đặt mới khi bạn sẵn sàng.':'Giao dịch mô phỏng bị từ chối. Không có tiền thật được thu và không có vé được phát hành.'}</p><div class="result-actions">${o.status==='unknown'?`<button class="btn" data-action="check-payment" data-code="${o.code}">Kiểm tra trạng thái đơn</button>`:`<button class="btn" data-action="retry" data-id="${o.show.id}">Chọn lại ghế ${ic('arrow')}</button>`}<a class="btn btn-outline" href="#/order/${o.code}">Chi tiết đơn</a><a class="text-link" href="#/support">Liên hệ hỗ trợ</a></div>${o.status==='unknown'?'<p class="small muted">Bản minh họa: nút kiểm tra sẽ nhận xác nhận thanh toán thành công giả lập. Trạng thái đơn được cập nhật trước khi cấp vé.</p>':''}</div>`;return `<div class="container result-page">${content}</div>`}
function authPage(mode){let headingText={login:'Chào bạn trở lại',register:'Bắt đầu những cuộc hẹn hay',forgot:'Tìm lại lối vào',verify:'Một bước xác thực nhỏ'}[mode];const register=mode==='register',verify=mode==='verify',forgot=mode==='forgot';return `<div class="container auth-page"><div class="auth-story"><span class="eyebrow light">LUMIÈRE CLUB</span><h1>Phim hay hơn<br>khi có <em>bạn.</em></h1><p>Lưu vé thật tiện. Tích điểm mỗi cuộc hẹn.<br>Và thêm nhiều niềm vui chờ phía trước.</p><div class="auth-orbit">${ic('star')}</div><span>YOUR NEXT MOVIE MOMENT.</span></div><div class="auth-form-wrap"><span class="eyebrow">${verify?'XÁC THỰC MINH HỌA':forgot?'KHÔI PHỤC TRUY CẬP':'THÀNH VIÊN LUMIÈRE'}</span><h2>${headingText}</h2><p class="muted">${verify?'Không gửi email hoặc SMS thật. Nhập mã minh họa 123456.':forgot?'Nhập email để bắt đầu khôi phục tài khoản giả lập.':register?'Miễn phí, chỉ mất vài phút.':'Đăng nhập mô phỏng bằng email và mật khẩu bất kỳ từ 6 ký tự.'}</p>${verify&&!pendingAuth?`<div class="notice">Chưa có yêu cầu xác thực. Bắt đầu lại tại màn hình đăng nhập.</div><a class="btn" href="#/login">Đăng nhập</a>`:`<form id="auth-form" data-mode="${mode}" novalidate>${register?'<label>Họ và tên<input name="name" required minlength="2" autocomplete="name" maxlength="80"></label>':''}${verify?'<label>Mã xác thực<input name="otp" inputmode="numeric" autocomplete="one-time-code" required pattern="123456" maxlength="6" placeholder="123456"></label>':`<label>Email<input name="email" type="email" required autocomplete="email" maxlength="120" placeholder="ban@example.com"></label>${!forgot?`<label>Mật khẩu minh họa<input name="password" type="password" minlength="6" required autocomplete="${register?'new-password':'current-password'}" placeholder="Từ 6 ký tự, không dùng mật khẩu thật"></label>`:''}`}${register?'<label class="checkbox-line"><input type="checkbox" name="terms"><span>Tôi đồng ý <a href="#/policy/terms">điều khoản</a> và <a href="#/policy/privacy">chính sách bảo mật</a>.</span></label>':''}<p class="field-error" id="auth-error" role="alert"></p><button class="btn full" type="submit">${verify?'Xác thực':forgot?'Tiếp tục khôi phục':register?'Tạo tài khoản':'Đăng nhập'} ${ic('arrow')}</button></form>`}<div class="auth-links">${mode==='login'?'<a href="#/forgot">Quên mật khẩu?</a><span>Chưa có tài khoản? <a href="#/register">Đăng ký</a></span>':'<a href="#/login">← Quay lại đăng nhập</a>'}</div><div class="notice"><div>${ic('info')}</div><p>Chỉ mô phỏng đăng nhập, không có xác thực bảo mật thật. Không lưu mật khẩu. Dùng <strong>demo@lumiere.local</strong> để xem tài khoản có lịch sử mẫu.</p></div><a class="back-link" href="#/lookup">Tra cứu vé không cần đăng nhập ${ic('arrow')}</a></div></div>`}
function accountNav(active){return `<nav class="account-nav" aria-label="Tài khoản"><a class="${active==='profile'?'active':''}" href="#/account">${ic('user')}Hồ sơ của tôi</a><a class="${active==='tickets'?'active':''}" href="#/tickets">${ic('ticket')}Vé & giao dịch</a><a href="#/membership">${ic('star')}Lumière Club</a><button data-action="logout">${ic('logout')}Đăng xuất</button></nav>`}
function userOrders(){return state.user?state.orders.filter(o=>o.userId===state.user.id||o.contact.email.toLowerCase()===state.user.email.toLowerCase()):[]}
function accountPage(){if(!state.user)return `<div class="container page">${empty('Những cuộc hẹn của riêng bạn','Đăng nhập để xem hồ sơ, tích điểm và quản lý vé.','Đăng nhập','#/login')}</div>`;return `<div class="container page">${title('TÀI KHOẢN LUMIÈRE','Xin chào, '+esc(state.user.name),'Thông tin của bạn giúp mỗi cuộc hẹn thuận tiện hơn.')}<div class="account-layout">${accountNav('profile')}<div class="panel"><h2>Hồ sơ của tôi</h2><form id="profile-form" novalidate>${contactFields(state.user)}<label>Ngày sinh (không bắt buộc)<input name="birthday" type="date" value="${esc(state.user.birthday||'')}" max="${D.today}"></label><p class="field-error" id="profile-error" role="alert"></p><button class="btn" type="submit">Lưu thay đổi ${ic('check')}</button></form></div></div></div>`}
function orderCard(o){const past=o.used||new Date(o.show.date+'T'+o.show.time+':00+07:00').getTime()<Date.now();return `<article class="order-card">${img(o.movie.art,o.movie.title)}<div class="order-card-main"><span class="small muted">${esc(o.code)}</span><h3>${o.movie.title}</h3><p>${o.cinema.name}<br><strong>${o.show.time}</strong> · ${dateLabel(o.show.date)} · Ghế ${o.seats.map(s=>s.id).join(', ')}</p><div class="order-statuses"><span class="status-pill ${o.status}">${paymentLabel[o.status]}</span><span class="status-pill neutral">Vé: ${o.status!=='paid'?'Chưa phát hành':o.used?'Đã sử dụng':past?'Đã qua giờ chiếu':'Chưa sử dụng'}</span></div></div><div class="order-card-actions"><strong>${money(o.total)}</strong><a class="btn btn-small ${o.status==='paid'?'':'btn-outline'}" href="#/${o.status==='paid'?'ticket':'order'}/${o.code}">${o.status==='paid'?'Mở vé':'Chi tiết đơn'}</a></div></article>`}
function ticketsPage(){if(!state.user)return `<div class="container page">${title('VÉ & GIAO DỊCH','Cuộc hẹn nào đang chờ bạn?')}<div class="guest-choices"><article class="panel"><h2>Đã có tài khoản?</h2><p>Đăng nhập để xem lịch sử và vé đã lưu.</p><a class="btn" href="#/login">Đăng nhập ${ic('arrow')}</a></article><article class="panel"><h2>Đặt vé bằng thông tin liên hệ?</h2><p>Tra cứu bằng mã đơn cùng email hoặc số điện thoại.</p><a class="btn btn-dark" href="#/lookup">Tra cứu vé ${ic('ticket')}</a></article></div></div>`;const tab=query.get('tab')||'upcoming',orders=userOrders().filter(o=>{const past=o.used||new Date(o.show.date+'T'+o.show.time+':00+07:00').getTime()<Date.now();return tab==='unfinished'?o.status!=='paid':o.status==='paid'&&(tab==='past'?past:!past)});return `<div class="container page">${title('VÉ & GIAO DỊCH','Những cuộc hẹn đã lưu')}<div class="account-layout">${accountNav('tickets')}<div><div class="tabs"><a class="${tab==='upcoming'?'active':''}" href="#/tickets?tab=upcoming">Sắp xem</a><a class="${tab==='past'?'active':''}" href="#/tickets?tab=past">Đã xem</a><a class="${tab==='unfinished'?'active':''}" href="#/tickets?tab=unfinished">Chưa hoàn tất</a></div>${orders.length?orders.map(orderCard).join(''):empty('Chưa có đơn trong mục này','Chọn một bộ phim để bắt đầu cuộc hẹn mới.')}<p class="small muted">Trạng thái thanh toán và trạng thái sử dụng vé được hiển thị riêng. Không có chức năng hoàn vé trong bản thiết kế.</p></div></div></div>`}
function lookupPage(){return `<div class="container page narrow">${title('VÉ CỦA BẠN LUÔN Ở ĐÂY','Tra cứu đơn đặt vé','Dành cho cả khách đặt vé không đăng nhập.')}<form id="lookup-form" class="panel" novalidate><label>Mã đơn<input name="code" required placeholder="Ví dụ: LM-DEMO01" autocomplete="off" maxlength="40"></label><label>Email hoặc số điện thoại đã đặt<input name="contact" required placeholder="Email hoặc số điện thoại" maxlength="120"></label><p id="lookup-error" class="field-error" role="alert"></p><button class="btn full" type="submit">Tra cứu đơn ${ic('search')}</button></form><div class="notice">${ic('info')}<p>Dữ liệu mẫu: mã <strong>LM-DEMO01</strong>, email <strong>demo@lumiere.local</strong>. Đơn mới chỉ được lưu trên trình duyệt bạn đã đặt vé.</p></div></div>`}
function orderPage(code,asTicket=false){const o=state.orders.find(o=>o.code===code);if(!o)return notFound();if(!orderAllowed(o))return `<div class="container page">${empty('Xác thực để xem đơn','Cần thông tin liên hệ đã đặt vé để mở đơn này.','Tra cứu đơn','#/lookup')}</div>`;if(asTicket&&o.status!=='paid')return resultPage(code);return `<div class="container page order-detail">${title(asTicket?'VÉ ĐIỆN TỬ':'CHI TIẾT GIAO DỊCH',asTicket?'Cuộc hẹn đã sẵn sàng':esc(o.code),'Lưu trên trình duyệt này · Đơn minh họa')} ${o.status==='paid'?ticket(o):`<div class="alert ${o.status==='failed'?'error':''}"><strong>${paymentLabel[o.status]}</strong><p>Chưa có vé được phát hành.</p><a class="text-link" href="#/result/${o.code}">${o.status==='unknown'?'Kiểm tra kết quả thanh toán':'Xem trạng thái đơn'} ${ic('arrow')}</a></div>`}<div class="order-detail-grid"><section class="panel"><h3>Thông tin suất và vé</h3><p><strong>${o.movie.title}</strong><br>${o.cinema.name} · ${o.room.name} · ${o.room.type}<br>${o.show.time} · ${dateLabel(o.show.date)} (UTC+7)<br>${o.show.format} · ${o.show.language}</p>${o.seats.map(s=>`<div class="line-item"><span>${s.id} · ${s.type}<small>${s.category} · ${s.people} khách/${s.unit}</small></span><strong>${money(s.price)}</strong></div>`).join('')}${o.foods.map(p=>`<div class="line-item"><span>${p.quantity} × ${p.name}<small>${p.contents}</small></span><strong>${money(p.price*p.quantity)}</strong></div>`).join('')}${o.foods.length?'<p class="small muted">Nhận đồ ăn tại quầy bằng mã đơn trước giờ chiếu.</p>':''}</section><section class="panel"><h3>Thanh toán & liên hệ</h3><p>Người nhận: ${esc(o.contact.name)}<br>${esc(o.contact.email)}<br>${esc(o.contact.phone)}</p><p>${esc(o.payment)}<br><strong>${paymentLabel[o.status]}</strong></p><dl class="price-breakdown"><div><dt>Tiền vé</dt><dd>${money(o.ticketTotal)}</dd></div><div><dt>Đồ ăn</dt><dd>${money(o.foodTotal)}</dd></div><div><dt>Giảm giá ${esc(o.promo||'')}</dt><dd>−${money(o.discount)}</dd></div><div class="total"><dt>Tổng cộng</dt><dd>${money(o.total)}</dd></div></dl></section></div><div class="result-actions">${o.status==='paid'?`<button class="btn" data-action="print">${ic('print')} In vé</button>`:''}<a class="btn btn-outline" href="#/tickets">Vé & giao dịch</a><a class="text-link" href="#/">Về trang chủ ${ic('arrow')}</a></div></div>`}
function membershipPage(){const pts=state.user?userOrders().filter(o=>o.status==='paid').reduce((a,o)=>a+Math.floor(o.total/10000),0):0;const tier=pts>=500?'Signature':pts>=100?'Explorer':'Discover',threshold=pts>=500?1000:pts>=100?500:100;return `<div class="container page">${title('LUMIÈRE CLUB','Vì bạn yêu điện ảnh','Mỗi lần đến rạp, thêm một điều đáng nhớ.')}<section class="membership-hero"><div><span class="eyebrow light">${state.user?'XIN CHÀO, '+esc(state.user.name.toUpperCase()):'A LITTLE MORE FOR MOVIE LOVERS'}</span><h2>${state.user?'Hạng '+tier:'Cuộc hẹn hay.<br>Quyền lợi thêm.'}</h2><p>${state.user?'Bạn đang có '+pts+' điểm. Cảm ơn vì đã cùng Lumière tạo nên những khoảnh khắc.':'Tạo tài khoản miễn phí để tích điểm, lưu vé và theo dõi những ưu đãi phù hợp với bạn.'}</p>${state.user?`<label class="point-progress">${pts} / ${threshold} điểm tới mốc kế tiếp <progress value="${Math.min(pts,threshold)}" max="${threshold}"></progress></label><a class="btn" href="#/tickets">Vé của tôi ${ic('arrow')}</a>`:'<a class="btn" href="#/register">Gia nhập Lumière Club '+ic('arrow')+'</a>'}</div><div class="membership-card"><span>LUMIÈRE CLUB</span>${ic('star')}<strong>${state.user?esc(state.user.name):'Your next movie moment.'}</strong><span>${state.user?tier.toUpperCase():'MEMBER · DISCOVER'}</span></div></section><div class="benefit-grid">${[['ticket','Vé ở ngay trong tay','Lưu đơn và mở vé nhanh từ tài khoản trên trình duyệt.'],['star','Tích điểm mỗi cuộc hẹn','1 điểm cho mỗi 10.000đ thực thanh toán, làm tròn xuống theo đơn.'],['mail','Ưu đãi đúng điều bạn thích','Xem rõ điều kiện theo rạp, loại phòng và đối tượng trước khi đặt.']].map(([i,t,p])=>`<article class="panel">${ic(i)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="panel"><h2>Mỗi chặng, một dấu ấn</h2><div class="tier-grid"><div><span>01</span><h3>Discover</h3><p>0–99 điểm<br>Lưu vé, tích điểm, cập nhật ưu đãi.</p></div><div><span>02</span><h3>Explorer</h3><p>100–499 điểm<br>Huy hiệu thành viên và quyền lợi nền tảng.</p></div><div><span>03</span><h3>Signature</h3><p>Từ 500 điểm<br>Huy hiệu thành viên và quyền lợi nền tảng.</p></div></div><p class="small muted">Hạng và điểm được tính từ đơn thanh toán thành công lưu cục bộ. Chưa hỗ trợ quy đổi điểm; các hạng chưa có mức giảm giá riêng. Không gửi thông báo thật.</p></div></div>`}
function offersPage(){return `<div class="container page">${title('THÊM NIỀM VUI CHO CUỘC HẸN','Ưu đãi dành cho bạn','Xem điều kiện trước khi đặt. Mỗi suất và loại vé có chính sách riêng.')}<div class="offer-grid">${D.offers.map(offerCard).join('')}</div><div class="notice">${ic('info')} Tất cả mã và quyền lợi là minh họa. Hiệu lực bộ mã: ${dateLabel(D.days[0])} – ${dateLabel(D.days[6])}.</div></div>`}
function offerDetail(id){const o=D.offers.find(o=>o.id===id);if(!o)return notFound();return `<div class="container page narrow">${title('ƯU ĐÃI / '+(o.kind==='member'?'LUMIÈRE CLUB':'LUMIÈRE MOMENTS'),o.title,o.subtitle)}${offerCard(o)}<section class="panel section-gap"><h2>Điều kiện áp dụng</h2><p>${o.rules}</p><dl class="film-info"><div><dt>Thời gian</dt><dd>${dateLabel(D.days[0])} – ${dateLabel(D.days[6])}</dd></div><div><dt>Rạp</dt><dd>${o.cinemas.map(id=>cinema(id).name).join(', ')}</dd></div><div><dt>Loại phòng</dt><dd>${o.rooms?.join(', ')||'Tất cả loại phòng'}</dd></div><div><dt>Mã minh họa</dt><dd>${o.kind==='member'?'Không dùng mã giảm giá':o.code}</dd></div></dl><p class="small muted">Không đại diện chính sách chính thức của thương hiệu khác. Giá vé ưu đãi theo đối tượng không được gộp với CHAO20.</p><a class="btn" ${o.id==='first'?'data-action="offer-city"':''} href="${o.kind==='member'?'#/membership':o.id==='first'?'#/schedule?mode=movie&offer=first&date='+D.days[1]:'#/schedule'}">${o.kind==='member'?'Khám phá thành viên':'Đặt vé áp dụng'} ${ic('arrow')}</a></section></div>`}
const faqs=[{group:'Đặt vé',items:[['Có cần tài khoản để đặt vé?','Không. Bạn có thể đặt bằng họ tên, email và số điện thoại. Thành viên có thêm lịch sử và điểm tích lũy.'],['Ghế được giữ trong bao lâu?','10 phút từ lúc bắt đầu lượt đặt. Khi hết thời gian, ghế được giải phóng; bạn cần chọn lại. Ghế đôi hoặc giường phải chọn nguyên đơn vị.'],['Giá vé được tính như thế nào?','Giá cuối cùng dựa theo suất, loại phòng, định dạng, hạng ghế và đối tượng vé. Buổi tối bắt đầu đúng 17:00. Ghế đôi tính theo cặp, giường tính theo giường cho 2 khách. Bộ dữ liệu không thiết lập giá lễ.']]},{group:'Thanh toán',items:[['Chưa xác định kết quả thì làm gì?','Mở chi tiết đơn và kiểm tra trạng thái trước khi thanh toán lại. Chưa có xác nhận thành công thì chưa có vé được phát hành.'],['Có thu tiền thật không?','Không. Đây là website mô phỏng chạy cục bộ. Không nhập số thẻ, OTP ngân hàng hoặc mật khẩu thật.']]},{group:'Sử dụng vé',items:[['Nhận và dùng vé như thế nào?','Sau xác nhận thanh toán thành công, mở vé điện tử từ trang kết quả, lịch sử hoặc tra cứu. QR ở đây chỉ minh họa, không quét được và không có giá trị vào rạp.'],['Nhận bắp và nước ở đâu?','Trong hành trình thực tế, xuất trình mã đơn ở quầy đồ ăn của đúng cụm rạp trước giờ chiếu.'],['Không thấy đơn trên thiết bị khác?','Dữ liệu chỉ lưu trong localStorage của trình duyệt. Không có máy chủ hoặc đồng bộ thiết bị; xóa dữ liệu trình duyệt sẽ xóa các đơn minh họa.']]}];
function supportPage(topic){return `<div class="container page">${title('LUÔN Ở ĐÂY KHI BẠN CẦN','Chúng mình có thể giúp gì?','Hướng dẫn cho những cuộc hẹn trọn vẹn hơn.')}<div class="support-layout"><nav class="account-nav" aria-label="Hỗ trợ"><a href="#/support" class="${!topic?'active':''}">Câu hỏi thường gặp</a><a href="#/support/guide">Hướng dẫn đặt vé</a><a href="#/support/contact">Liên hệ hỗ trợ</a><a href="#/support/demo">Phạm vi mô phỏng</a><a href="#/policy/purchase">Điều kiện mua vé</a></nav><div>${topic==='contact'?`<section class="panel"><h2>Gửi yêu cầu hỗ trợ</h2><p>Email minh họa: support@lumiere.example<br>Hotline minh họa: 1900 0188 · 08:00–22:00 (UTC+7)<br>Không có bộ phận tiếp nhận thật.</p><form id="support-form" novalidate><label>Họ tên<input name="name" required minlength="2" maxlength="80"></label><label>Email<input name="email" type="email" required maxlength="120"></label><label>Nhóm yêu cầu<select name="topic"><option>Đặt vé</option><option>Thanh toán</option><option>Sử dụng vé</option><option>Tài khoản</option></select></label><label>Mã đơn (nếu có)<input name="code" maxlength="40"></label><label>Nội dung<textarea name="message" required minlength="10" maxlength="2000" rows="5"></textarea></label><p class="field-error" id="support-error" role="alert"></p><button class="btn">Gửi yêu cầu minh họa ${ic('arrow')}</button></form></section>`:topic==='guide'?`<section class="panel"><h2>Đặt vé trong 7 bước</h2><ol class="guide-steps">${['Khám phá phim hoặc chọn rạp gần bạn.','Chọn ngày và suất với đúng định dạng, ngôn ngữ, loại phòng.','Chọn ghế, đối tượng vé và kiểm tra điều kiện. Ghế được giữ trong 10 phút.','Thêm bắp, nước nếu muốn.','Kiểm tra đơn, điền liên hệ, áp dụng mã phù hợp.','Chọn phương thức, xác nhận điều khoản và thanh toán mô phỏng.','Chờ kết quả xác nhận thành công rồi mở vé; kiểm tra đơn nếu chưa xác định kết quả.'].map(t=>`<li>${t}</li>`).join('')}</ol><a class="btn" href="#/schedule">Bắt đầu đặt vé ${ic('arrow')}</a></section>`:topic==='demo'?`<section class="panel"><h2>Một rạp phim, trong bản minh họa</h2><p>Thương hiệu, phim, diễn viên, ảnh vector, địa chỉ, liên hệ và giá vé đều là dữ liệu hư cấu.</p><p>Website chạy hoàn toàn bằng HTML, CSS và JavaScript. Không có backend, không gửi email/SMS, không thu tiền và không xác thực danh tính thật. Mã 123456 chỉ dành cho xác thực giả lập.</p><p>Đăng nhập nhận mật khẩu minh họa bất kỳ từ 6 ký tự và không lưu mật khẩu. Không dùng mật khẩu thật hoặc nhập dữ liệu thanh toán nhạy cảm.</p><p>Ghế giữ được phối hợp giữa các tab cùng trình duyệt, không phải tồn kho thực tế. Đơn và dữ liệu cá nhân lưu trên trình duyệt này, có thể xem hoặc thay đổi bằng công cụ trình duyệt.</p><p>Công cụ dưới các bước đặt vé cho phép kết thúc giữ chỗ hoặc chọn kết quả thanh toán giả lập. Chưa có kết quả thành công thì chưa cấp vé.</p><button class="btn btn-outline" data-action="reset">Khôi phục dữ liệu mẫu</button></section>`:faqs.map(g=>`<section class="faq-section"><h2>${g.group}</h2>${g.items.map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`).join('')}</div></div></div>`}
function policyPage(type){const policies={terms:{name:'Điều khoản sử dụng',sections:[['Phạm vi sử dụng','Đây là sản phẩm giao diện mô phỏng. Các thương hiệu, phim, giá và chính sách không đại diện cho đơn vị đang hoạt động. Không tạo giao dịch pháp lý hoặc cam kết cung cấp dịch vụ xem phim thật.'],['Tài khoản minh họa','Chỉ nhập thông tin giả lập. Cơ chế đăng nhập không xác minh danh tính và không phù hợp để bảo vệ dữ liệu thật. Người dùng có thể đăng xuất hoặc khôi phục dữ liệu bất kỳ lúc nào.'],['Trải nghiệm có trách nhiệm','Tôn trọng phân loại độ tuổi. Kiểm tra kỹ rạp, suất, ngôn ngữ, loại phòng, vị trí ghế và thông tin nhận vé. Không dùng QR minh họa tại rạp thật.']]},privacy:{name:'Chính sách bảo mật',sections:[['Dữ liệu được lưu','Tên, email, số điện thoại, ngày sinh tùy chọn, lựa chọn ghế, đồ ăn và đơn minh họa lưu trong localStorage của trình duyệt. Mật khẩu và dữ liệu thanh toán nhạy cảm không được lưu.'],['Mục đích và giới hạn','Dữ liệu chỉ phục vụ trải nghiệm giả lập, không gửi về máy chủ, không đồng bộ thiết bị. Người có quyền truy cập cùng trình duyệt có thể xem dữ liệu này. Mở bản đồ dẫn sang dịch vụ bên ngoài.'],['Xóa dữ liệu','Dùng “Khôi phục dữ liệu mẫu” ở chân trang để xóa dữ liệu của ứng dụng rồi khởi tạo lại mẫu. Có thể xóa localStorage trong phần cài đặt trình duyệt. Không xóa dữ liệu website khác.']]},purchase:{name:'Điều kiện mua vé',sections:[['Trước khi xác nhận','Kiểm tra phim, cụm rạp, phòng, ngày giờ UTC+7, định dạng 2D/3D, ngôn ngữ, độ tuổi và số khách. Ghế đôi hoặc giường bán nguyên đơn vị cho 2 khách. Mỗi đơn tối đa 8 khách.'],['Giá và đối tượng','Giá cuối cùng ghi theo vé/cặp/giường. Từ 17:00 bao gồm đúng 17:00. Trẻ em: dưới 12 tuổi và cao dưới 1,3 m với phim P/K, phim K cần người giám hộ; học sinh–sinh viên có thẻ; cao tuổi từ 60 có giấy tờ. Không giảm theo đối tượng cho ghế đôi/giường và phòng Cao cấp/Giường nằm. Các mã có điều kiện riêng.'],['Giữ chỗ và thanh toán','Giữ chỗ 10 phút. Hết giờ phải chọn lại. Chỉ cấp vé khi trạng thái thanh toán đã thành công. Khi chưa xác định kết quả, kiểm tra đơn trước khi tạo thanh toán mới. Không có chức năng hoàn vé trong phạm vi này.'],['Vào rạp và đồ ăn','Trong hành trình thực tế, đến trước 15 phút, mang giấy tờ về độ tuổi và loại vé nếu cần. Đồ ăn nhận tại đúng cụm rạp bằng mã đơn. QR và thông tin liên hệ trên website này chỉ minh họa.']]}};const p=policies[type];if(!p)return notFound();return `<article class="container page narrow policy">${title('THÔNG TIN LUMIÈRE',p.name,'Nội dung mẫu cho giao diện minh họa, không phải chính sách của một rạp đang hoạt động.')}${p.sections.map(([t,b],i)=>`<section><h2>${i+1}. ${t}</h2><p>${b}</p></section>`).join('')}<a class="text-link" href="#/support">Trung tâm hỗ trợ ${ic('arrow')}</a></article>`}
function notFound(){return `<div class="container page not-found"><span>404</span><h1>Có vẻ bạn đã lạc sang một cảnh khác.</h1><p>Trang bạn tìm không tồn tại. Câu chuyện hay vẫn đang chờ bạn.</p><a class="btn" href="#/">Về trang chủ ${ic('arrow')}</a><a class="text-link" href="#/support">Cần hỗ trợ?</a></div>`}
let modalPreviousFocus=null;
function closeModal(){const root=$('#modal-root');if(!root.firstChild)return;root.innerHTML='';document.body.classList.remove('modal-open');modalPreviousFocus?.focus()}
function modal(content){modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="icon-button modal-close" data-action="close-modal" aria-label="Đóng">${ic('close')}</button>${content}</section></div>`;document.body.classList.add('modal-open');$('.modal').focus()}
function trailer(id){const m=movie(id);if(!m)return;modal(`<span class="eyebrow">LUMIÈRE ORIGINAL STORIES</span><h2 id="modal-title">${m.title}</h2><video class="trailer-video" controls playsinline preload="metadata" poster="assets/images/${m.art}.svg"><source src="assets/videos/${m.id}.mp4" type="video/mp4"><track kind="captions" src="assets/videos/${m.id}.vtt" srclang="vi" label="Tiếng Việt" default>Trình duyệt của bạn không phát được video.</video><p>${m.blurb}</p><p class="small muted">Teaser đồ họa minh họa, không âm thanh. Phim và hình ảnh hư cấu, không phải trailer của một phim đã phát hành.</p><a class="btn" href="#/movie/${m.id}" data-action="close-modal">Thông tin & lịch chiếu ${ic('arrow')}</a>`)}
function filterMovies(){const f=$('#movie-filters');if(!f)return;const val=Object.fromEntries(new FormData(f)),ms=D.movies.filter(m=>m.status===(query.get('tab')==='soon'?'soon':'now')&&m.title.toLocaleLowerCase('vi').includes(val.search.toLocaleLowerCase('vi'))&&(!val.genre||m.genre===val.genre)&&(!val.format||m.formats.includes(val.format))&&(!val.age||m.age===val.age));$('#movie-results').innerHTML=ms.length?ms.map(movieCard).join(''):empty('Chưa có phim phù hợp','Thử thay đổi thể loại, định dạng hoặc độ tuổi.','Xóa bộ lọc','#/movies?tab='+(query.get('tab')==='soon'?'soon':'now'));$('#movie-count').textContent=ms.length+' phim phù hợp';}
function filterCinemas(){const f=$('#cinema-filters');if(!f)return;const val=Object.fromEntries(new FormData(f)),cs=D.cinemas.filter(c=>(!val.city||c.city===val.city)&&(c.name+' '+c.address).toLocaleLowerCase('vi').includes(val.search.toLocaleLowerCase('vi')));$('#cinema-results').innerHTML=cs.length?cs.map(cinemaCard).join(''):empty('Chưa tìm thấy rạp','Thử đổi tỉnh thành hoặc từ khóa.','Xem tất cả rạp','#/cinemas')}
function routeParse(){let raw=location.hash.slice(1)||'/';const [path,qs='']=raw.split('?');route=path;query=new URLSearchParams(qs)}
function render(scroll=true){routeParse();closeModal();const parts=route.split('/').filter(Boolean);let html;const root=parts[0]||'';
try{switch(root){case '':html=home();break;case 'movies':html=moviesPage();break;case 'movie':html=movieDetail(parts[1]);break;case 'schedule':html=schedulePage();break;case 'cinemas':html=cinemasPage();break;case 'cinema':html=cinemaDetail(parts[1]);break;case 'experiences':html=experiencesPage();break;case 'search':html=searchPage();break;case 'booking':html=bookingPage(parts[1]);break;case 'result':html=resultPage(parts[1]);break;case 'login':case 'register':case 'forgot':case 'verify':html=authPage(root);break;case 'account':html=accountPage();break;case 'tickets':html=ticketsPage();break;case 'lookup':html=lookupPage();break;case 'ticket':case 'order':html=orderPage(parts[1],root==='ticket');break;case 'membership':html=membershipPage();break;case 'offers':html=offersPage();break;case 'offer':html=offerDetail(parts[1]);break;case 'support':html=supportPage(parts[1]);break;case 'policy':html=policyPage(parts[1]);break;default:html=notFound();}
$('#main').innerHTML=html;header();document.body.classList.toggle('in-booking',root==='booking');document.title=($('#main h1')?.textContent||'Chạm vào điện ảnh')+' | Lumière Cinema';if(!storageOK)$('#main').insertAdjacentHTML('afterbegin','<div class="container alert error">Trình duyệt không cho phép lưu cục bộ. Dữ liệu chỉ giữ tạm trong phiên này; hãy mở bằng trình duyệt thông thường để lưu đơn.</div>');if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}if(root==='movies')filterMovies();tick();if(query.get('booking')==='1')setTimeout(()=>$('#showtimes')?.scrollIntoView({behavior:'smooth',block:'start'}),80);
}catch(e){console.error(e);$('#main').innerHTML=`<div class="container page">${empty('Không thể tải nội dung','Bạn có thể về trang chủ và thử lại. Nếu dữ liệu mẫu đã bị chỉnh sửa, hãy khôi phục dữ liệu ở chân trang.','Về trang chủ','#/')}</div>`;header()}}
function errorAt(selector,text,field){$(selector).textContent=text;field?.focus()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(el.disabled)return;
switch(a){case 'summary':$('.order-summary')?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'offer-city':state.city='TP. Hồ Chí Minh';save();break;case 'menu':{const nav=$('.mobile-nav'),isOpen=!nav.hidden;nav.hidden=isOpen;el.setAttribute('aria-expanded',!isOpen);break}case 'home-tab':{const tab=el.dataset.tab;$$('.home-tabs button').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===tab));$('#home-movies').innerHTML=D.movies.filter(m=>m.status===tab).slice(0,4).map(movieCard).join('');break}case 'trailer':trailer(el.dataset.id);break;case 'close-modal':closeModal();break;case 'select-show':startBooking(el.dataset.id);break;case 'seat':toggleSeat(el.dataset.id);break;case 'zoom':{const map=$('.seat-map');map.classList.toggle('zoomed');el.textContent=map.classList.contains('zoomed')?'Thu nhỏ sơ đồ':'Phóng to sơ đồ';break}case 'food':{const x=bookingContext(),p=D.products.find(p=>p.id===el.dataset.id);if(!x||x.b.expired||!p?.cinemas.includes(x.c.id))return;const val=Math.max(0,Math.min(10,(x.b.foods[p.id]||0)+Number(el.dataset.delta)));x.b.foods[p.id]=val;save();refreshBooking();break}case 'to-food':case 'to-checkout':{const err=validateReservation();if(err)return toast(err);go(a==='to-food'?'#/booking/food':'#/booking/checkout');break}case 'apply-promo':{const f=$('#checkout-form');syncContact(f);state.booking.promo=f.elements.promo.value.trim().toUpperCase();save();refreshBooking();break}case 'remove-promo':state.booking.promo='';save();refreshBooking();break;case 'login-return':returnTo=location.hash;state.resumeAfterAuth=returnTo;syncContact($('#checkout-form'));save();go('#/login');break;case 'logout':state.user=null;save();toast('Đã đăng xuất tài khoản.');go('#/');break;case 'expire':expireBooking();break;case 'restart':{const x=bookingContext();if(!x)return;const pending=state.orders.find(o=>o.sourceBooking===x.b.showId&&['processing','unknown'].includes(o.status));if(pending){grantOrder(pending.code);toast('Kiểm tra đơn chưa có kết quả trước khi đặt lại.');go('#/result/'+pending.code);return}releaseSeats();x.b.seats=[];x.b.expiresAt=Date.now()+600000;x.b.expired=false;save();go('#/booking/seats');break}case 'retry':{const o=state.orders.find(o=>o.show.id===el.dataset.id&&['unknown','processing'].includes(o.status));if(o){go('#/result/'+o.code);return}if(state.booking)state.booking.expiresAt=0;startBooking(el.dataset.id);break}case 'check-payment':{const o=state.orders.find(o=>o.code===el.dataset.code);if(!o||!orderAllowed(o)||o.status!=='unknown')return;el.disabled=true;el.textContent='Đang kiểm tra…';setTimeout(()=>{const conflict=o.seats.some(s=>soldLocally(o.show.id,s.id));if(conflict){o.status='failed'}else{o.status='paid';releaseBy(o.sourceBooking,o.holdOwner);if(state.booking?.showId===o.show.id)state.booking=null}save();render(false);toast(o.status==='paid'?'Đã nhận xác nhận thanh toán mô phỏng thành công.':'Ghế đã được bán cho đơn khác. Giao dịch mô phỏng không thành công.')},1200);break}case 'print':window.print();break;case 'reset':modal(`<h2 id="modal-title">Khôi phục dữ liệu mẫu?</h2><p>Các đơn, hồ sơ, lượt giữ ghế và lựa chọn của ứng dụng trong trình duyệt này sẽ bị xóa. Bộ dữ liệu mẫu ban đầu sẽ được tạo lại.</p><div class="result-actions"><button class="btn" data-action="confirm-reset">Khôi phục dữ liệu</button><button class="btn btn-outline" data-action="close-modal">Giữ dữ liệu hiện tại</button></div>`);break;case 'confirm-reset':{releaseSeats();state={version:1,city:'TP. Hồ Chí Minh',user:null,profiles:{},booking:null,orders:[]};write(HOLD_KEY,{});write('lumiere-guest-access',[]);pendingAuth=null;paymentBusy=false;seed();save();closeModal();go('#/');toast('Đã khôi phục dữ liệu mẫu.');break}}
});
document.addEventListener('change',e=>{if(e.target.id==='city'){if($('#checkout-form'))syncContact($('#checkout-form'));state.city=e.target.value;save();const q=new URLSearchParams(query);q.delete('cinema');go('#'+route+(q.size?'?'+q:''));if(location.hash.slice(1)===route)render(false);return}if(e.target.matches('[data-category]')){const x=bookingContext(),item=x?.b.seats.find(s=>s.id===e.target.dataset.category);if(item&&D.categories(x.s).includes(e.target.value)){item.category=e.target.value;save();refreshBooking()}}if(e.target.closest('#movie-filters'))filterMovies();if(e.target.closest('#cinema-filters'))filterCinemas();if(e.target.closest('#checkout-form')){syncContact($('#checkout-form'));if(e.target.name==='email'&&state.booking.promo){$('.order-summary').outerHTML=bookingSummary();tick()}}});
document.addEventListener('input',e=>{if(e.target.closest('#movie-filters'))filterMovies();if(e.target.closest('#cinema-filters'))filterCinemas();if(e.target.closest('#checkout-form')&&['name','email','phone'].includes(e.target.name))syncContact($('#checkout-form'));});
document.addEventListener('submit',e=>{const f=e.target;e.preventDefault();const v=Object.fromEntries(new FormData(f));switch(f.id){case 'quick-book':go(`#/movie/${v.movie}?date=${v.date}&cinema=${v.cinema}&booking=1`);break;case 'global-search':go('#/search?q='+encodeURIComponent(v.q.trim()));break;case 'movie-filters':filterMovies();break;case 'cinema-filters':filterCinemas();break;case 'schedule-filter':go(`#/schedule?mode=${f.dataset.mode}&${f.dataset.mode}=${v[f.dataset.mode]}&date=${v.date}${f.dataset.offer?'&offer='+f.dataset.offer:''}`);break;case 'detail-filters':go(`#/movie/${f.dataset.movie}?date=${f.dataset.date}&cinema=${v.cinema}&format=${v.format}`);break;case 'checkout-form':pay(f);break;case 'auth-form':{
const mode=f.dataset.mode;if(mode==='verify'){if(v.otp!=='123456')return errorAt('#auth-error','Mã chưa đúng. Nhập mã minh họa 123456.',f.elements.otp);if(!pendingAuth)return go('#/login');if(pendingAuth.mode==='forgot'){pendingAuth=null;toast('Xác thực giả lập thành công. Bạn có thể đăng nhập bằng mật khẩu minh họa từ 6 ký tự.');return go('#/login')}const email=pendingAuth.email,profile=state.profiles[email]||{id:email,name:pendingAuth.name||(email==='demo@lumiere.local'?'Minh Anh':'Bạn yêu phim'),email,phone:email==='demo@lumiere.local'?'0901234567':''};state.user={...profile};state.profiles[email]={...profile};pendingAuth=null;save();toast('Đã đăng nhập mô phỏng.');const dest=state.resumeAfterAuth||returnTo;if(state.booking){for(const k of ['name','email','phone'])if(!state.booking.contact[k])state.booking.contact[k]=state.user[k]||''}delete state.resumeAfterAuth;save();returnTo='#/account';go(dest);break}
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email.trim()))return errorAt('#auth-error','Email chưa đúng định dạng.',f.elements.email);if(mode!=='forgot'&&v.password.length<6)return errorAt('#auth-error','Mật khẩu minh họa cần từ 6 ký tự.',f.elements.password);if(mode==='register'&&v.name.trim().length<2)return errorAt('#auth-error','Họ tên cần ít nhất 2 ký tự.',f.elements.name);if(mode==='register'&&!v.terms)return errorAt('#auth-error','Vui lòng đồng ý điều khoản trước khi đăng ký.',f.elements.terms);const email=v.email.trim().toLowerCase();if(mode==='register'&&state.profiles[email])return errorAt('#auth-error','Email đã có hồ sơ cục bộ. Vui lòng đăng nhập.',f.elements.email);pendingAuth={mode,email,name:v.name?.trim()};f.reset();go('#/verify');break}case 'profile-form':{const c={name:v.name.trim(),email:v.email.trim().toLowerCase(),phone:v.phone.trim()},err=contactError(c);if(err)return errorAt('#profile-error',err);if(v.birthday>D.today)return errorAt('#profile-error','Ngày sinh không thể ở tương lai.',f.elements.birthday);if(state.profiles[c.email]&&state.profiles[c.email].id!==state.user.id)return errorAt('#profile-error','Email đã thuộc hồ sơ khác trong bộ dữ liệu.',f.elements.email);const old=state.user.email;state.user={...state.user,...c,birthday:v.birthday};delete state.profiles[old];state.profiles[c.email]={...state.user};save();render(false);toast('Đã cập nhật hồ sơ.');break}case 'lookup-form':{const o=state.orders.find(o=>o.code.toUpperCase()===v.code.trim().toUpperCase()&&(o.contact.email.toLowerCase()===v.contact.trim().toLowerCase()||o.contact.phone===v.contact.trim()));if(!o)return errorAt('#lookup-error','Không tìm thấy đơn khớp mã và thông tin liên hệ. Kiểm tra lại dữ liệu trên trình duyệt này.');grantOrder(o.code);go('#/order/'+o.code);break}case 'support-form':{if(v.name.trim().length<2)return errorAt('#support-error','Họ tên cần ít nhất 2 ký tự.',f.elements.name);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email))return errorAt('#support-error','Email chưa đúng định dạng.',f.elements.email);if(v.message.trim().length<10)return errorAt('#support-error','Mô tả yêu cầu cần ít nhất 10 ký tự.',f.elements.message);modal(`<h2 id="modal-title">Yêu cầu minh họa đã hoàn tất</h2><p>Cảm ơn ${esc(v.name.trim())}. Giao diện đã kiểm tra nội dung hợp lệ. Không có yêu cầu hoặc email nào được gửi thật.</p><button class="btn" data-action="close-modal">Đã hiểu</button>`);f.reset();break}}
});
document.addEventListener('keydown',e=>{if(e.target.closest?.('.home-tabs')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.home-tabs button'),idx=tabs.indexOf(e.target),next=(e.key==='Home'?0:e.key==='End'?tabs.length-1:e.key==='ArrowRight'?(idx+1)%tabs.length:(idx+tabs.length-1)%tabs.length);tabs[next]?.focus();tabs[next]?.click()}const m=$('.modal');if(!m)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...m.querySelectorAll('a,button,input,select,textarea,video,[tabindex="0"]')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===m)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('a[href^="#/"]')&&$('#checkout-form'))syncContact($('#checkout-form'));if(e.target.closest('a[href="#/login"]')&&route.startsWith('/booking/')){returnTo=location.hash;state.resumeAfterAuth=returnTo;save()}});
window.addEventListener('hashchange',()=>render());
window.addEventListener('storage',e=>{if(e.key===HOLD_KEY&&route==='/booking/seats')refreshBooking();if(e.key===KEY){const incoming=read(KEY,state);state.orders=incoming.orders;state.profiles=incoming.profiles;state.user=incoming.user;if(route.startsWith('/result/')||route.startsWith('/order/'))render(false)}});
setInterval(()=>{tick();state.orders.filter(o=>o.status==='processing'&&o.resolveAt<=Date.now()).forEach(o=>resolvePayment(o.code));},1000);
render();
})();
